// Model-based exploration: seeded random command sequences, each step checked against a reference
// model interpreted from the compiled specification.
//
// Generated by `ess verify conform synthesize --target typescript`. Do not edit: change the
// specification and regenerate.
//
// # What this asks that the suite does not
//
// The suite asks one fixed question per scenario. This walks paths nobody wrote — a view that drops
// rows after the fifth, a refusal that still writes, an identity reused on the fourth create, a
// state that cannot be re-entered a third time — and checks after every step the outcome, the
// error, the direct events and their determined payload fields, every parameterless view over an
// entity (polling an `eventual` one), identity uniqueness and every invariant. A failure is shrunk
// to a shorter trace that still fails the same way.
//
// # External branches
//
// An outcome declared `external:` (with or without an eligibility `when:`) is a choice the
// explorer may take: where it is eligible, a seeded draw picks between it and the ordinary branch,
// the target is asked to arrange it through `configureExternalOutcome`, and the step then expects
// it. Once a command has had a branch arranged in a sequence, the arrangement may still hold, so
// the explorer no longer expects that command's ordinary branch where an external one is eligible.
// A branch the target cannot arrange is reported `unarrangeable`, never as a disagreement.
//
// # A port, not a second opinion
//
// `src/go/explore.go` is this file in Go, function for function. The random draws, their order and
// every sorted enumeration are part of the contract, so one seed names one sequence in both
// languages and both report the same trace for it.
//
// # The model it reads
//
// `ir.json` beside `suite.json`: the compact IR, the exact bytes the suite's `spec_digest` is taken
// over. It is read only after that digest matches, so a package whose two files came from different
// specifications is refused rather than explored against the wrong model.

import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { refusePrivateExploration } from './one_time_response.js';
import { join } from 'node:path';

import { facts, fromNode, present, TruthFalse, TruthTrue, TruthUnknown } from './predicate.js';
import type { FactSource, Operand, Predicate, Truth } from './predicate.js';
import {
  asNumber,
  byteCompare,
  equal,
  errorText,
  goMarshal,
  isObject,
  isUnsupported,
  newHarness,
  ranked,
  sortStrings,
  strictJSON,
} from './runtime.js';
import type {
  Answer,
  CommandRequest,
  CommandResult,
  Node,
  Row,
  Target,
  ViewRequest,
} from './runtime.js';

/** What one exploration is asked to do. */
export interface ExploreOptions {
  /** Sequences to run, seeded `1…seeds`. Default 200. */
  seeds?: number;
  /** Commands per sequence. Default 60. */
  steps?: number;
  /** Run exactly this one sequence, overriding `seeds`: how a reported failure is replayed. */
  seed?: number;
}

/** One command or view left out of every sequence, and why. */
export interface Exclusion {
  subject: string;
  reason: string;
}

/** A disagreement: its seed, what disagreed, and the shortest trace found that still shows it. */
export interface ExploreFailure {
  seed: number;
  message: string;
  trace: string[];
  originalLength: number;
  shrinkComplete: boolean;
}

/** What an exploration found. Every list is sorted. */
export interface ExploreResult {
  sequences: number;
  steps: number;
  /** Commands actually run, across every sequence and none of the shrinking replays. */
  executed: number;
  /** `command/outcome` for every outcome a step took. */
  reached: string[];
  /** Declared outcomes of included commands that no step took. */
  unreached: string[];
  excluded: Exclusion[];
  /** Every declared outcome of an excluded command. */
  excludedOutcomes: string[];
  /** What the model could not place, such as a view filter over a field no command set. */
  undetermined: string[];
  /** Draws the specification does not decide, which were redrawn rather than executed. */
  ambiguous: string[];
  /**
   * Every declared `external:` branch and how far the exploration got with it, in order of
   * `outcome`. Absent when the specification declares none, so a result without external branches
   * keeps its bytes.
   */
  external?: ExternalReach[];
  failure?: ExploreFailure;
}

/** One declared `external:` branch and whether a step took it. */
export interface ExternalReach {
  /** `command/outcome`. */
  outcome: string;
  /** What the specification says decides it. */
  cause: string;
  /**
   * `reached`, `unreached`, `unarrangeable` (the target refused to arrange it, so no step could
   * take it) or `excluded` (its command was left out).
   */
  reach: 'reached' | 'unreached' | 'unarrangeable' | 'excluded';
  /** Why the target could not arrange it, for `unarrangeable` only. */
  reason?: string;
}

/** What `assertExplored` accepts. */
export interface AssertOptions {
  /**
   * Accept outcomes of excluded commands, and external outcomes the target could not arrange. An
   * explicit, reviewable opt-out.
   */
  allowExcluded?: boolean;
}

export const DEFAULT_SEEDS = 200;
export const DEFAULT_STEPS = 60;
const ATTEMPTS_PER_STEP = 20;
const SHRINK_REPLAYS = 1000;
const INTEGERS = [-1, 0, 1, 2, 3, 100];
const TEXTS = ['', 'a', 'b'];

/** The refusal when `ir.json` is not the model `suite.json` was synthesized from. */
export const MODEL_MISMATCH =
  '`ir.json` and `suite.json` come from different specifications; regenerate the package';

// ---- randomness -------------------------------------------------------------------------------

/**
 * mulberry32 over a 32-bit state that starts at the seed.
 *
 * `next` is the 32-bit output divided by 2^32, which binary64 holds exactly, so the Go port draws
 * the same numbers.
 */
export class Mulberry32 {
  private state: number;

  constructor(seed: number) {
    this.state = seed >>> 0;
  }

  nextUint32(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return (t ^ (t >>> 14)) >>> 0;
  }

  next(): number {
    return this.nextUint32() / 4294967296;
  }

  int(lo: number, hi: number): number {
    return lo + Math.floor(this.next() * (hi - lo + 1));
  }

  pick<T>(items: T[]): T {
    return items[Math.floor(this.next() * items.length)] as T;
  }

  chance(p: number): boolean {
    return this.next() < p;
  }
}

// ---- the model document -------------------------------------------------------------------------

function packageFile(name: string): string {
  try {
    return readFileSync(new URL(`../${name}`, import.meta.url), 'utf8');
  } catch (error) {
    throw new Error(`explore: cannot read \`${name}\`: ${errorText(error)}`);
  }
}

/**
 * The compiled model, after its digest has been checked against the suite's.
 *
 * Throws when either file is absent or unreadable, or when the two disagree.
 */
export function loadModel(
  irText: string = packageFile('ir.json'),
  suiteText: string = packageFile('suite.json'),
): Node {
  const body = irText.endsWith('\n') ? irText.slice(0, -1) : irText;
  const digest = createHash('sha256').update(body, 'utf8').digest('hex');
  const suite = strictJSON(suiteText);
  const declared =
    isObject(suite) && isObject(suite.provenance) ? suite.provenance.spec_digest : null;
  if (digest !== declared) {
    throw new Error(MODEL_MISMATCH);
  }
  const model = strictJSON(body);
  refusePrivateExploration(model);
  return model;
}

/** An object's values in byte order of key. */
function sortedValues(value: Node): Node[] {
  if (!isObject(value)) return [];
  return sortStrings(Object.keys(value)).map((key) => value[key]);
}

function list(value: Node): Node[] {
  return Array.isArray(value) ? value : [];
}

function nonEmpty(value: Node): boolean {
  if (Array.isArray(value)) return value.length > 0;
  if (isObject(value)) return Object.keys(value).length > 0;
  return value !== null && value !== undefined;
}

// ---- input types --------------------------------------------------------------------------------

type Kind =
  | { kind: 'integer' | 'boolean' | 'string' | 'uuid' | 'decimal' | 'timestamp' }
  | { kind: 'enum'; variants: string[] }
  | { kind: 'struct'; fields: InputField[] }
  | { kind: 'identity'; entity: string; base: Kind }
  | { kind: 'optional'; base: Kind }
  | { kind: 'unsupported'; why: string };

type InputField = [string, Kind, string?];

function identityOwner(ir: Node, type: string): string | null {
  for (const entity of sortedValues(ir.entities)) {
    const ref = entity?.identity?.type_ref;
    if (ref?.kind === 'declared' && ref.name === type) return entity.name;
  }
  return null;
}

/**
 * The kind of values an input of type `ref` is drawn from. With `concurrent` it also draws a `decimal`, a `timestamp`,
 * and a type whose values are constrained: concurrent exploration does not judge an answer by this
 * model, `ess` does, so a drawn value outside the constraint is a question the target answers and the
 * checker judges.
 */
function resolveKind(ir: Node, ref: Node, depth = 0, concurrent = false): Kind {
  if (depth > 32) return { kind: 'unsupported', why: 'nested too deeply' };
  if (ref?.kind === 'optional') {
    const base = resolveKind(ir, ref.of, depth + 1, concurrent);
    return base.kind === 'unsupported' ? base : { kind: 'optional', base };
  }
  if (ref?.kind === 'primitive') {
    switch (ref.name) {
      case 'integer':
      case 'boolean':
      case 'string':
      case 'uuid':
        return { kind: ref.name };
      case 'decimal':
      case 'timestamp':
        if (concurrent) return { kind: ref.name };
        return { kind: 'unsupported', why: `a \`${ref.name}\`` };
      default:
        return { kind: 'unsupported', why: `a \`${ref.name}\`` };
    }
  }
  if (ref?.kind !== 'declared') return { kind: 'unsupported', why: `a \`${ref?.kind}\`` };
  const body = ir.types?.[ref.name]?.body;
  if (
    !concurrent &&
    (list(body?.invariants).length > 0 || (body?.alphabet !== undefined && body?.alphabet !== null))
  ) {
    return { kind: 'unsupported', why: `\`${ref.name}\`, which constrains its values` };
  }
  if (body?.kind === 'newtype') {
    const base = resolveKind(ir, body.of, depth + 1, concurrent);
    if (base.kind === 'unsupported') return base;
    const owner = identityOwner(ir, ref.name);
    return owner === null ? base : { kind: 'identity', entity: owner, base };
  }
  if (body?.kind === 'enum') {
    const variants = list(body.variants).map((variant: Node) =>
      typeof variant === 'string' ? variant : String(variant?.name),
    );
    if (variants.length === 0)
      return { kind: 'unsupported', why: `\`${ref.name}\`, which has no variants` };
    return { kind: 'enum', variants };
  }
  if (body?.kind === 'struct') {
    const fields: InputField[] = [];
    for (const field of list(body.fields)) {
      const kind = resolveKind(ir, field.type_ref, depth + 1, concurrent);
      if (kind.kind === 'unsupported') return kind;
      fields.push([field.name, kind, field.naming?.presence]);
    }
    return { kind: 'struct', fields };
  }
  return { kind: 'unsupported', why: `\`${ref.name}\`, a \`${body?.kind}\`` };
}

// ---- predicates ---------------------------------------------------------------------------------

const TEXT_OPERATORS = ['starts_with', 'ends_with', 'contains'];

function walk(predicate: Predicate, visit: (node: Predicate) => void): void {
  visit(predicate);
  for (const child of predicate.children) walk(child, visit);
  if (predicate.body) walk(predicate.body, visit);
}

/** Every fact path a predicate reads, sorted. */
function paths(predicate: Predicate): string[] {
  const found = new Set<string>();
  walk(predicate, (node) => {
    if (node.kind === 'compare') {
      if (node.left.isFact) found.add(node.left.path);
      if (node.right.isFact) found.add(node.right.path);
    } else if (node.kind === 'forall' || node.kind === 'exists') {
      found.add(node.over);
    } else if (node.path !== '') {
      found.add(node.path);
    }
  });
  return sortStrings([...found]);
}

/** The first path a predicate reads that `row` does not hold. */
function missing(predicate: Predicate, row: Row): string {
  const source = facts(row);
  return paths(predicate).find((path) => !source.has(path)) ?? paths(predicate)[0] ?? '';
}

function parsed(node: Node): Predicate | string {
  try {
    const predicate = fromNode(node);
    let text: string | null = null;
    walk(predicate, (child) => {
      if (text === null && TEXT_OPERATORS.includes(child.kind)) text = child.kind;
    });
    if (text !== null) return `it uses \`${text}\`, which this explorer does not evaluate`;
    return predicate;
  } catch (error) {
    return `it cannot be read: ${errorText(error)}`;
  }
}

/**
 * A command's draw pools. `fieldIntegers` and `fieldTexts` are the pools of the input paths whose
 * own pool differs from the command's (beyond10x/ess#223): the command's, with the input's
 * `example:` and, for a text, that example (or the path itself) cut or cycled to n-1, n and n+1
 * characters for each `.count` literal compared with the input. Every other path draws from the
 * command's pool.
 */
interface Pools {
  integers: number[];
  texts: string[];
  fieldIntegers: Map<string, number[]>;
  fieldTexts: Map<string, string[]>;
  /**
   * The variants of each enum input with an `example:`, and the example where it is not one of
   * them. Validation admits only a declared variant, so for a validated specification this is the
   * variants as declared and the draw does not move.
   */
  fieldEnums: Map<string, string[]>;
}

/** The longest text a `.count` boundary is drawn at, synthesis's `MAX_COUNT_WITNESS`. */
const MAX_COUNT = 1024;

/** The integer pool the input at `path` draws from. */
function integersAt(pools: Pools, path: string): number[] {
  return pools.fieldIntegers.get(path) ?? pools.integers;
}

/** The text pool the input at `path` draws from. */
function textsAt(pools: Pools, path: string): string[] {
  return pools.fieldTexts.get(path) ?? pools.texts;
}

/** The pool an enum input at `path` draws from, `variants` where it has no example. */
function enumsAt(pools: Pools, path: string, variants: string[]): string[] {
  return pools.fieldEnums.get(path) ?? variants;
}

/** `value` as a whole number binary64 holds exactly, if it is one. */
function safeWhole(value: Node): number | null {
  if (
    typeof value === 'string' ||
    typeof value === 'boolean' ||
    value === null ||
    value === undefined
  )
    return null;
  const [number, ok] = asNumber(value);
  return ok && Number.isSafeInteger(number) ? number : null;
}

/**
 * For each input path a `.count` of which a guard compares with a whole literal, the lengths n-1, n
 * and n+1 of every such literal n, from 0 to `MAX_COUNT`. A guard over the input reads its paths as
 * they are; a predicate over the stored row reads the input under `input.`, and its other paths
 * are the row's.
 */
function counts(inputGuards: Predicate[], storedGuards: Predicate[]): Map<string, Set<number>> {
  const found = new Map<string, Set<number>>();
  const visit =
    (stored: boolean) =>
    (node: Predicate): void => {
      if (node.kind !== 'compare') return;
      const pairs: [Operand, Operand][] = [
        [node.left, node.right],
        [node.right, node.left],
      ];
      for (const [fact, literal] of pairs) {
        if (!fact.isFact || literal.isFact || !fact.path.endsWith('.count')) continue;
        let path = fact.path.slice(0, -'.count'.length);
        if (path === '') continue;
        if (stored) {
          if (!path.startsWith('input.')) continue;
          path = path.slice('input.'.length);
        }
        const n = safeWhole(literal.literal);
        if (n === null) continue;
        for (const length of [n - 1, n, n + 1]) {
          if (length < 0 || length > MAX_COUNT) continue;
          if (!found.has(path)) found.set(path, new Set());
          found.get(path)!.add(length);
        }
      }
    };
  for (const guard of inputGuards) walk(guard, visit(false));
  for (const guard of storedGuards) walk(guard, visit(true));
  return found;
}

/**
 * `text` at exactly `length` characters: its first `length` when it has that many, otherwise its
 * own characters cycled from its start, and `plain`'s when it is empty. Synthesis's rule for a text
 * cut to a `.count` boundary (`witness.rs` `resize`).
 */
function resize(text: string, length: number, plain: string): string {
  let source = [...text];
  if (source.length === 0) source = [...plain];
  if (source.length === 0) return '';
  const out: string[] = [];
  for (let index = 0; index < length; index += 1) out.push(source[index % source.length] as string);
  return out.join('');
}

/** The kind a value is drawn as once an `Optional` and an identity are looked through. */
function leafKind(kind: Kind): Kind {
  while (kind.kind === 'optional' || kind.kind === 'identity') kind = kind.base;
  return kind;
}

/**
 * Gives each input path its own pool where it differs from the command's (beyond10x/ess#223).
 * `examples` is the command's `examples`, by top-level input name.
 */
function fieldPools(
  pools: Pools,
  inputs: InputField[],
  examples: Node,
  lengths: Map<string, Set<number>>,
): void {
  const visit = (path: string, kind: Kind, example: Node, hasExample: boolean): void => {
    const leaf = leafKind(kind);
    if (leaf.kind === 'struct') {
      for (const [name, field] of leaf.fields) visit(`${path}.${name}`, field, undefined, false);
    } else if (leaf.kind === 'enum') {
      if (!hasExample || typeof example !== 'string') return;
      pools.fieldEnums.set(
        path,
        leaf.variants.includes(example) ? [...leaf.variants] : [...leaf.variants, example],
      );
    } else if (leaf.kind === 'integer') {
      const n = hasExample ? safeWhole(example) : null;
      if (n === null) return;
      pools.fieldIntegers.set(
        path,
        [...new Set([n, ...pools.integers])].sort((left, right) => left - right),
      );
    } else if (leaf.kind === 'string') {
      const text = hasExample && typeof example === 'string' ? example : null;
      const counted = lengths.get(path) ?? new Set<number>();
      if (text === null && counted.size === 0) return;
      const set = new Set<string>(pools.texts);
      if (text !== null) set.add(text);
      const base = text ?? path;
      for (const length of counted) set.add(resize(base, length, path));
      pools.fieldTexts.set(path, sortStrings([...set]));
    }
  };
  for (const [name, kind] of inputs) {
    const hasExample = isObject(examples) && Object.prototype.hasOwnProperty.call(examples, name);
    visit(name, kind, hasExample ? examples[name] : undefined, hasExample);
  }
}

/** The literals a command's guards compare against, as draw pools. */
function pools(guards: Predicate[]): Pools {
  const integers = new Set<number>(INTEGERS);
  const texts = new Set<string>(TEXTS);
  const literal = (value: Node): void => {
    if (typeof value === 'string') {
      texts.add(value);
      return;
    }
    if (typeof value === 'boolean' || value === null || value === undefined) return;
    const [number, ok] = asNumber(value);
    if (ok && Number.isSafeInteger(number)) {
      integers.add(number - 1);
      integers.add(number);
      integers.add(number + 1);
    }
  };
  for (const guard of guards) {
    walk(guard, (node) => {
      if (node.kind === 'compare') {
        if (!node.left.isFact) literal(node.left.literal);
        if (!node.right.isFact) literal(node.right.literal);
      } else if (node.kind === 'any_of' || node.kind === 'none_of') {
        node.values.forEach(literal);
      }
    });
  }
  return {
    integers: [...integers].sort((left, right) => left - right),
    texts: sortStrings([...texts]),
    fieldIntegers: new Map(),
    fieldTexts: new Map(),
    fieldEnums: new Map(),
  };
}

// ---- the plan: what is explored, and what is left out -------------------------------------------

interface Command {
  name: string;
  actor: string;
  node: Node;
  inputs: InputField[];
  guards: Map<string, Predicate>;
  /** Every branch selected by the stored row (beyond10x/ess#221), by outcome name. */
  rows: Map<string, RowGuard>;
  pools: Pools;
}

/**
 * A condition read from the subject's stored row: its held state (`subject_state`, `state_change`),
 * one stored enum field (`subject_field`) or a predicate over its stored fields
 * (`subject_predicate`), each with an optional guard over the input.
 */
interface RowGuard {
  kind: string;
  states: Set<string>;
  field: string;
  equals: string;
  stored: Predicate | null;
  input: Predicate | null;
}

/** Every condition read from the subject's stored row. */
const ROW_KINDS = ['subject_state', 'state_change', 'subject_field', 'subject_predicate'];

interface Plan {
  ir: Node;
  system: string;
  commands: Command[];
  views: Node[];
  excluded: Exclusion[];
  excludedCommands: Set<string>;
  declared: Map<string, string[]>;
  /** Every declared external branch, in declaration order. */
  externals: { command: string; id: string; cause: string }[];
  /** `command/outcome` for every external branch the target refused to arrange, and its reason. */
  unarrangeable: Map<string, string>;
  /**
   * Every command excluded only because exploration cannot draw one of its inputs (a list, say): a
   * precondition supplies its input as a literal, so it may still send one (beyond10x/ess#205). No
   * sequence draws it.
   */
  sendable: Map<string, Command>;
}

/** True for an outcome an external cause decides. */
function isExternal(outcome: Node): boolean {
  const kind = outcome?.condition?.kind;
  return kind === 'external' || kind === 'external_when';
}

function effectRefusal(outcome: Node): string | null {
  const subject = outcome.subject;
  if (subject === null || subject === undefined) return null;
  const from = subject.instance?.from;
  const allowed =
    (subject.effect === 'creates' && from === 'observed') ||
    ((subject.effect === 'moves' || subject.effect === 'updates') && from === 'supplied');
  return allowed
    ? null
    : `outcome \`${outcome.name}\` ${subject.effect} its subject from \`${from}\``;
}

/** A stored-row condition as the explorer evaluates it, or why it cannot. */
function rowOf(condition: Node): RowGuard | string {
  const row: RowGuard = {
    kind: String(condition.kind),
    states: new Set(),
    field: '',
    equals: '',
    stored: null,
    input: null,
  };
  const parse = (node: Node): Predicate | null | string =>
    node === null || node === undefined ? null : parsed(node);
  let input: Predicate | null | string = null;
  switch (row.kind) {
    case 'subject_state':
      // One state is written as the state itself, a list (ess/18) as a list.
      if (typeof condition.state === 'string') row.states.add(condition.state);
      for (const state of list(condition.state)) row.states.add(String(state));
      input = parse(condition.predicate);
      break;
    case 'state_change':
      for (const state of list(condition.states)) row.states.add(String(state));
      input = parse(condition.predicate);
      break;
    case 'subject_field':
      row.field = typeof condition.field === 'string' ? condition.field : '';
      row.equals = typeof condition.equals === 'string' ? condition.equals : '';
      input = parse(condition.predicate);
      break;
    case 'subject_predicate': {
      const stored = parse(condition.predicate);
      if (typeof stored === 'string') return stored;
      row.stored = stored;
      input = parse(condition.input);
      break;
    }
  }
  if (typeof input === 'string') return input;
  row.input = input;
  return row;
}

/** The `existing_instance` branch of a command node, or undefined. */
function existingOutcome(node: Node): Node | undefined {
  return list(node.outcomes).find(
    (outcome: Node) => outcome.condition?.kind === 'existing_instance',
  );
}

/**
 * Where a creating branch puts its identity: the entity, and the input field that names the
 * identity, or `''` where the implementation generates it.
 */
interface Address {
  entity: string;
  field: string;
}

/**
 * The distinct addresses of a command node's creating branches, in declaration order. Where there
 * is more than one, which one an `existing_instance` branch reads depends on the branch selected
 * (`interpret::execute` `existence::existing`).
 */
function addresses(node: Node): Address[] {
  const out: Address[] = [];
  for (const outcome of list(node.outcomes)) {
    const subject = outcome?.subject;
    if (subject?.effect !== 'creates') continue;
    const instance = subject.instance;
    const identity = typeof instance?.field?.name === 'string' ? instance.field.name : '';
    const address: Address = {
      entity: typeof subject.entity === 'string' ? subject.entity : '',
      field: '',
    };
    for (const payload of list(outcome.payload)) {
      if (payload?.event !== instance?.event) continue;
      for (const field of list(payload.fields)) {
        const kind = field?.value?.kind;
        if (
          field?.target === identity &&
          (kind === 'input_field' || kind === 'input_or_generated')
        ) {
          address.field = typeof field.value.field === 'string' ? field.value.field : '';
        }
      }
    }
    if (!out.some((known) => known.entity === address.entity && known.field === address.field)) {
      out.push(address);
    }
  }
  return out;
}

/**
 * What exploration may call and read. With `concurrent` it resolves inputs as `resolveKind` does then
 * and keeps a command no actor may invoke, which is then sent with no actor.
 */
function plan(ir: Node, concurrent = false): Plan {
  const excluded: Exclusion[] = [];
  const excludedCommands = new Set<string>();
  const sendable = new Map<string, Command>();
  const declared = new Map<string, string[]>();
  const externals: { command: string; id: string; cause: string }[] = [];
  const actorFor = new Map<string, string>();
  for (const actor of sortedValues(ir.actors)) {
    for (const command of list(actor.may)) {
      if (!actorFor.has(command)) actorFor.set(command, actor.name);
    }
  }

  const commands: Command[] = [];
  for (const node of sortedValues(ir.commands)) {
    const outcomes = list(node.outcomes);
    declared.set(
      node.name,
      outcomes.map((outcome: Node) => String(outcome.name)),
    );
    for (const outcome of outcomes) {
      if (isExternal(outcome)) {
        externals.push({
          command: node.name,
          id: `${node.name}/${outcome.name}`,
          cause: typeof outcome.condition.cause === 'string' ? outcome.condition.cause : '',
        });
      }
    }
    let reason: string | null = null;
    for (const outcome of outcomes) {
      const kind = outcome.condition?.kind;
      // A condition read from the stored row, and existence of the identity a creation names, are
      // decided from the model's rows (beyond10x/ess#221). Concurrent exploration does not draw
      // them: it keeps the commands it always drew.
      const stored = !concurrent && (kind === 'existing_instance' || ROW_KINDS.includes(kind));
      if (
        reason === null &&
        kind !== 'when' &&
        kind !== 'otherwise' &&
        kind !== 'wrong_state' &&
        kind !== 'unknown_instance' &&
        kind !== 'external' &&
        kind !== 'external_when' &&
        !stored
      ) {
        reason = `outcome \`${outcome.name}\` has a \`${kind}\` condition`;
      }
    }
    const existing = existingOutcome(node);
    if (reason === null && existing !== undefined && addresses(node).length > 1) {
      reason = `outcome \`${existing.name}\` answers an existing instance of creations that name it differently`;
    }
    for (const outcome of outcomes) reason ??= effectRefusal(outcome);
    for (const outcome of outcomes) {
      if (
        reason === null &&
        !concurrent &&
        outcome.replays !== undefined &&
        outcome.replays !== null
      ) {
        reason = `outcome \`${outcome.name}\` replays a retained result`;
      }
    }
    // Why exploration cannot draw an input, kept apart from every other reason so that a command
    // excluded for it alone stays sendable by a precondition. It is reported in the order it always
    // was: after the outcome reasons, before the guard and actor ones.
    let undrawable: string | null = null;
    const inputs: InputField[] = [];
    for (const field of list(node.input)) {
      const kind = resolveKind(ir, field.type_ref, 0, concurrent);
      if (undrawable === null && kind.kind === 'unsupported') {
        undrawable = `input \`${field.name}\` is ${kind.why}`;
      }
      inputs.push([field.name, kind, field.naming?.presence]);
    }
    const guards = new Map<string, Predicate>();
    const rows = new Map<string, RowGuard>();
    const ordered: Predicate[] = [];
    // `inputGuards` read the input as it is; `storedGuards` read the row, and the input under
    // `input.`.
    const inputGuards: Predicate[] = [];
    const storedGuards: Predicate[] = [];
    let later: string | null = null;
    for (const outcome of outcomes) {
      const kind = outcome.condition?.kind;
      if (reason !== null || later !== null) continue;
      if (ROW_KINDS.includes(kind)) {
        const row = rowOf(outcome.condition);
        if (typeof row === 'string') {
          later = `the guard of \`${outcome.name}\`: ${row}`;
          continue;
        }
        rows.set(outcome.name, row);
        if (row.stored !== null) {
          ordered.push(row.stored);
          storedGuards.push(row.stored);
        }
        if (row.input !== null) {
          ordered.push(row.input);
          inputGuards.push(row.input);
        }
        continue;
      }
      if (kind !== 'when' && kind !== 'external_when') continue;
      const guard = parsed(outcome.condition.predicate);
      if (typeof guard === 'string') later = `the guard of \`${outcome.name}\`: ${guard}`;
      else {
        guards.set(outcome.name, guard);
        ordered.push(guard);
        inputGuards.push(guard);
      }
    }
    const actor = actorFor.get(node.name) ?? (concurrent ? '' : undefined);
    if (later === null && actor === undefined) later = 'no actor may invoke it';
    const drawn = pools(ordered);
    fieldPools(drawn, inputs, node.examples, counts(inputGuards, storedGuards));
    const command: Command = {
      name: node.name,
      actor: actor ?? '',
      node,
      inputs,
      guards,
      rows,
      pools: drawn,
    };
    if (reason === null && later === null && undrawable !== null) sendable.set(node.name, command);
    reason ??= undrawable ?? later;
    if (reason !== null || actor === undefined) {
      excluded.push({ subject: node.name, reason: reason ?? 'no actor may invoke it' });
      excludedCommands.add(node.name);
      continue;
    }
    commands.push(command);
  }

  const views: Node[] = [];
  for (const view of sortedValues(ir.views)) {
    let reason: string | null = null;
    if (nonEmpty(view.params)) reason = 'it declares parameters';
    else if (nonEmpty(view.group_by)) reason = 'it groups its rows';
    else if (list(view.fields).some((field: Node) => nonEmpty(field.aggregate)))
      reason = 'it aggregates';
    else if (!isObject(ir.entities?.[view.source]))
      reason = `its source \`${view.source}\` is not an entity`;
    else if (
      view.filter !== undefined &&
      view.filter !== null &&
      typeof parsed(view.filter) === 'string'
    ) {
      reason = `its filter: ${parsed(view.filter) as string}`;
    }
    if (reason !== null) excluded.push({ subject: view.name, reason });
    else views.push(view);
  }
  return {
    ir,
    system: String(ir.system),
    commands,
    views,
    excluded,
    excludedCommands,
    declared,
    externals,
    unarrangeable: new Map(),
    sendable,
  };
}

function exclude(p: Plan, subject: string, reason: string): void {
  p.excluded.push({ subject, reason });
  if (p.commands.some((command) => command.name === subject)) {
    p.commands = p.commands.filter((command) => command.name !== subject);
    p.excludedCommands.add(subject);
  }
  p.views = p.views.filter((view) => view.name !== subject);
}

// ---- the reference model ------------------------------------------------------------------------

interface Rec {
  id: Node;
  fields: Row;
}

class Model {
  readonly records = new Map<string, Rec[]>();

  of(entity: string): Rec[] {
    let found = this.records.get(entity);
    if (found === undefined) {
      found = [];
      this.records.set(entity, found);
    }
    return found;
  }

  find(entity: string, id: Node): Rec | undefined {
    return this.of(entity).find((record) => equal(record.id, id));
  }
}

/** A value an outcome gives a field, or `undefined` where the model does not know it. */
const CLEARED = Symbol('cleared');

function readPath(value: Node, path: string): Node {
  let current = value;
  for (const segment of path.split('.')) {
    if (!isObject(current) || !Object.prototype.hasOwnProperty.call(current, segment))
      return undefined;
    current = current[segment];
  }
  return current;
}

function setPath(value: Node, path: string, to: Node): void {
  const segments = path.split('.');
  let current = value;
  for (const segment of segments.slice(0, -1)) current = current[segment];
  current[segments[segments.length - 1] as string] = to;
}

function literalValue(ir: Node, text: Node, type: Node): Node {
  const kind = resolveKind(ir, type);
  const base = kind.kind === 'identity' ? kind.base : kind;
  if (typeof text !== 'string') return undefined;
  switch (base.kind) {
    case 'integer': {
      if (!/^-?[0-9]+$/.test(text)) return undefined;
      const number = Number(text);
      return Number.isSafeInteger(number) ? number : undefined;
    }
    case 'boolean':
      return text === 'true' ? true : text === 'false' ? false : undefined;
    case 'string':
    case 'uuid':
    case 'enum':
      return text;
    default:
      return undefined;
  }
}

function optionalType(ir: Node, type: Node): boolean {
  for (let depth = 0; depth <= 32; depth += 1) {
    if (type?.kind === 'optional') return true;
    if (type?.kind !== 'declared') return false;
    const body = ir.types?.[type.name]?.body;
    if (body?.kind !== 'newtype') return false;
    type = body.of;
  }
  return false;
}

function valueOf(ir: Node, value: Node, input: Row, type: Node): Node | typeof CLEARED {
  switch (value?.kind) {
    case 'input_field': {
      const found = readPath(input, String(value.field));
      return found === undefined && optionalType(ir, value.type_ref) ? null : found;
    }
    case 'literal':
      return literalValue(ir, value.value, type);
    case 'cleared':
      return CLEARED;
    default:
      return undefined;
  }
}

/** Typed absence is knowledge; only genuinely unknown model fields are skipped. */
function valueAgrees(
  ir: Node,
  type: Node,
  naming: Node,
  expected: Node,
  actual: Node,
  present: boolean,
  depth = 0,
): boolean {
  if (depth > 32) return false;
  if (type?.kind === 'optional') {
    if (expected === null || expected === undefined) {
      if (naming?.presence === 'null_when_absent') return present && actual === null;
      if (naming?.presence === 'omitted_when_absent') return !present;
      return !present || actual === null;
    }
    return valueAgrees(ir, type.of, {}, expected, actual, present, depth + 1);
  }
  if (type?.kind === 'declared') {
    const body = ir.types?.[type.name]?.body;
    if (body?.kind === 'newtype')
      return valueAgrees(ir, body.of, naming, expected, actual, present, depth + 1);
    if (body?.kind === 'struct' && isObject(expected)) {
      const fields = list(body.fields);
      const names = new Set(fields.map((field: Node) => field.name));
      return (
        present &&
        isObject(actual) &&
        Object.keys(actual).every((name) => names.has(name)) &&
        fields.every((field: Node) =>
          valueAgrees(
            ir,
            field.type_ref,
            field.naming,
            expected[field.name],
            actual[field.name],
            Object.prototype.hasOwnProperty.call(actual, field.name),
            depth + 1,
          ),
        )
      );
    }
  }
  return present && equal(expected, actual);
}

/**
 * What the model says one step may take. For `take`, `outcome` is the ordinary branch (undefined
 * when none holds) and `externals` the external branches eligible for this input and this subject,
 * in declaration order; at least one of the two is present. A `take` with no ordinary branch
 * carries in `names` the ambiguity it stands in for, reported if no external branch can be
 * arranged. `unknown` and `undetermined` carry in `reason` a guard the model cannot
 * evaluate: over the input, which excludes the command, or over a stored field no command set,
 * which is redrawn and reported.
 */
type Decision =
  | { kind: 'take'; outcome: Node; externals: Node[]; names?: string[] }
  | { kind: 'ambiguous'; names: string[] }
  | { kind: 'unknown'; reason: string }
  | { kind: 'undetermined'; reason: string };

function suppliedOutcome(command: Command): Node | undefined {
  return list(command.node.outcomes).find(
    (outcome: Node) => outcome.subject?.instance?.from === 'supplied',
  );
}

function unknownOutcome(command: Command): Node | undefined {
  return list(command.node.outcomes).find(
    (outcome: Node) => outcome.condition?.kind === 'unknown_instance',
  );
}

function terminal(command: Command, outcome: Node, input: Row, model: Model): Node {
  const subject = outcome?.subject;
  if (
    subject?.instance?.from === 'supplied' &&
    model.find(subject.entity, readPath(input, subject.instance.field.name)) === undefined
  ) {
    return unknownOutcome(command) ?? outcome;
  }
  return outcome;
}

/**
 * Whether an outcome is an input-guarded refusal: a `when:` and an `error:`, which Entity Runtime
 * tries before every other branch.
 */
function isInputRefusal(outcome: Node): boolean {
  return (
    outcome.condition?.kind === 'when' && typeof outcome.error === 'string' && outcome.error !== ''
  );
}

/**
 * Which branch a step takes, in Entity Runtime's order (beyond10x/ess#235): the input-guarded
 * refusals, the first declared whose guard holds; then the accepting guarded branch that holds, or
 * the default; then, where that branch moves from a state no move of the command starts from, the
 * wrong-state branch.
 */
function decide(command: Command, input: Row, model: Model): Decision {
  const outcomes = list(command.node.outcomes);
  const supplied = suppliedOutcome(command);
  const record =
    supplied === undefined
      ? undefined
      : model.find(supplied.subject.entity, readPath(input, supplied.subject.instance.field.name));
  const moves = outcomes.filter((outcome: Node) => outcome.subject?.effect === 'moves');
  const starts = new Set<string>(
    moves.flatMap((outcome: Node) => list(outcome.subject.transition.from)),
  );
  const wrong = outcomes.find((outcome: Node) => outcome.condition?.kind === 'wrong_state');
  const source = facts(input);
  // Entity Runtime's order (beyond10x/ess#235): an input-guarded refusal, the first declared whose
  // guard holds, answers before anything else is read — the record, its state, a provider, and
  // every accepting branch it overlaps.
  for (const outcome of outcomes) {
    if (!isInputRefusal(outcome)) continue;
    const guard = command.guards.get(outcome.name) as Predicate;
    const truth = guard.evaluate(source);
    if (truth === TruthUnknown) {
      return {
        kind: 'unknown',
        reason: `the guard of \`${outcome.name}\` (${guard}) is unknown over a generated input`,
      };
    }
    if (truth === TruthTrue) return { kind: 'take', outcome, externals: [] };
  }
  // Existence (beyond10x/ess#221): a creation naming an identity a record already carries is
  // refused by `existing_instance`, before the held state and every accepting branch.
  const existing = existingOutcome(command.node);
  if (existing !== undefined) {
    for (const address of addresses(command.node)) {
      if (address.field === '') continue;
      const id = readPath(input, address.field);
      if (id !== undefined && id !== null && model.find(address.entity, id) !== undefined) {
        return { kind: 'take', outcome: existing, externals: [] };
      }
    }
  }
  if (supplied !== undefined && record === undefined && unknownOutcome(command) === undefined) {
    return { kind: 'ambiguous', names: ['no record for the supplied instance'] };
  }
  // A branch selected by the stored row reads a row that must exist: an identity no record carries
  // is the unknown-instance answer before any of them is read.
  if (command.rows.size > 0 && record === undefined) {
    const missingRecord = unknownOutcome(command);
    if (missingRecord !== undefined) return { kind: 'take', outcome: missingRecord, externals: [] };
    return { kind: 'ambiguous', names: ['no record for the supplied instance'] };
  }
  // What a step may take where no ordinary branch can be: the eligible external branches alone,
  // or `otherwise`, when there are none.
  const orExternal = (otherwise: { kind: 'ambiguous'; names: string[] }): Decision => {
    const eligible = eligibleExternals(command, outcomes, source, record);
    if (typeof eligible === 'string') return { kind: 'unknown', reason: eligible };
    if (eligible.length > 0) {
      return { kind: 'take', outcome: undefined, externals: eligible, names: otherwise.names };
    }
    return otherwise;
  };
  // A move from a state no move of this command starts from is the wrong-state answer, whichever
  // guarded branch or default made it (entity-core `admit_state`); a branch that moves nothing
  // answers in every state. That includes an eligible external branch: Entity Runtime sorts it
  // ahead of the default, so an arranged one answers here, and the draw offers it beside the
  // wrong-state answer. Where the subject is stranded, only externals that move nothing are
  // eligible (`eligibleExternals` drops a move from a state it does not start from).
  const stranded = record !== undefined && moves.length > 0 && !starts.has(record.fields.state);
  const wrongState = (): Decision => {
    if (wrong !== undefined) {
      const eligible = eligibleExternals(command, outcomes, source, record);
      if (typeof eligible === 'string') return { kind: 'unknown', reason: eligible };
      return { kind: 'take', outcome: wrong, externals: eligible };
    }
    return orExternal({
      kind: 'ambiguous',
      names: [`no outcome for state ${record!.fields.state}`],
    });
  };

  // The held row (beyond10x/ess#221): the branches selected by the stored row — its held state, a
  // stored field, a predicate over its fields — whose input guard holds too, before every accepting
  // guard (the precedence order, step 4), the first declared that holds answering. An accepting
  // guard declared before it that holds as well is the one branch the interpreter
  // (`interpret::execute::select`, declaration order) and the precedence order answer differently,
  // so that draw alone the specification does not decide, and it is redrawn.
  const { held, decision: undecided } = heldBranch(command, outcomes, record as Rec, source, input);
  if (undecided !== undefined) return undecided;
  const holding: Node[] = [];
  if (held !== undefined) {
    const earlier: string[] = [];
    for (const outcome of outcomes) {
      if (String(outcome.name) === String(held.name)) break;
      if (outcome.condition?.kind !== 'when' || isInputRefusal(outcome)) continue;
      const guard = command.guards.get(outcome.name) as Predicate;
      const truth = guard.evaluate(source);
      if (truth === TruthUnknown) {
        return {
          kind: 'unknown',
          reason: `the guard of \`${outcome.name}\` (${guard}) is unknown over a generated input`,
        };
      }
      if (truth === TruthTrue) earlier.push(String(outcome.name));
    }
    if (earlier.length > 0) {
      return orExternal({ kind: 'ambiguous', names: [...earlier, String(held.name)] });
    }
    holding.push(held);
  }
  for (const outcome of outcomes) {
    if (held !== undefined || outcome.condition?.kind !== 'when' || isInputRefusal(outcome))
      continue;
    const guard = command.guards.get(outcome.name) as Predicate;
    const truth = guard.evaluate(source);
    if (truth === TruthUnknown) {
      return {
        kind: 'unknown',
        reason: `the guard of \`${outcome.name}\` (${guard}) is unknown over a generated input`,
      };
    }
    if (truth === TruthTrue) holding.push(outcome);
  }
  // The external branches this input and subject make eligible. Their guards state eligibility,
  // not the verdict, so they take no part in choosing the ordinary branch; and where no ordinary
  // branch can be taken, they still can.
  const externals = eligibleExternals(command, outcomes, source, record);
  if (typeof externals === 'string') return { kind: 'unknown', reason: externals };
  let selected: Node;
  if (holding.length > 1) {
    // Where every branch that holds moves and the subject rests where no move starts, each of them
    // is the wrong-state answer, so the overlap decides nothing.
    if (stranded && holding.every((outcome) => outcome.subject?.effect === 'moves')) {
      return wrongState();
    }
    return orExternal({ kind: 'ambiguous', names: holding.map((outcome) => String(outcome.name)) });
  } else if (holding.length === 1) {
    selected = holding[0];
  } else {
    selected = outcomes.find((outcome: Node) => outcome.condition?.kind === 'otherwise');
    if (selected === undefined) {
      return orExternal({ kind: 'ambiguous', names: ['no outcome holds'] });
    }
  }
  if (
    selected.subject?.effect === 'moves' &&
    record !== undefined &&
    !list(selected.subject.transition.from).includes(record.fields.state)
  ) {
    if (stranded) return wrongState();
    const names = [String(selected.name)];
    if (wrong !== undefined) names.push(String(wrong.name));
    return orExternal({ kind: 'ambiguous', names });
  }
  return { kind: 'take', outcome: terminal(command, selected, input, model), externals };
}

/**
 * Whether a branch selected by the stored row holds for `record` and this input, or the decision a
 * guard the model cannot evaluate stands for: `unknown` where a path of the input is missing, which
 * is so for every draw of that input, and `undetermined` where a stored field is unset or null,
 * which another record need not share.
 */
function rowHolds(
  command: Command,
  name: string,
  row: RowGuard,
  record: Rec,
  source: FactSource,
  input: Row,
): boolean | Decision {
  let stored: Truth = TruthTrue;
  let unread: Unread = { path: '', input: false, null: false };
  switch (row.kind) {
    case 'subject_state':
    case 'state_change':
      stored = row.states.has(String(record.fields.state)) ? TruthTrue : TruthFalse;
      break;
    case 'subject_field': {
      const has = Object.prototype.hasOwnProperty.call(record.fields, row.field);
      const value = record.fields[row.field];
      if (!has) {
        stored = TruthUnknown;
        unread = { path: row.field, input: false, null: false };
      } else if (value === null || value === undefined) {
        stored = TruthUnknown;
        unread = { path: row.field, input: false, null: true };
      } else {
        stored = equal(value, row.equals) ? TruthTrue : TruthFalse;
      }
      break;
    }
    case 'subject_predicate': {
      const combined: Row = { ...record.fields, input };
      stored = (row.stored as Predicate).evaluate(facts(combined));
      if (stored === TruthUnknown) unread = unreadIn(row.stored as Predicate, combined);
      break;
    }
  }
  if (stored === TruthFalse) return false;
  let guard: Truth = TruthTrue;
  if (row.input !== null) {
    guard = row.input.evaluate(source);
    if (guard === TruthUnknown) {
      return {
        kind: 'unknown',
        reason: `the guard of \`${name}\` (${row.input}) is unknown over a generated input`,
      };
    }
  }
  if (unread.input) {
    return {
      kind: 'unknown',
      reason: `the guard of \`${name}\` (${row.stored}) is unknown over a generated input`,
    };
  }
  if (guard === TruthFalse) return false;
  if (stored === TruthUnknown) {
    const why = unread.null ? 'which the row holds as null' : 'which no command set';
    return {
      kind: 'undetermined',
      reason: `${command.name} guard of \`${name}\` reads ${unread.path}, ${why}`,
    };
  }
  return true;
}

/**
 * The path that left a stored-row predicate Unknown: a path of the input under `input.` the draw
 * does not hold, or else a stored field the row does not hold or holds as null.
 */
interface Unread {
  path: string;
  input: boolean;
  null: boolean;
}

/**
 * What left `predicate` Unknown over `row`: the input is blamed only where one of its paths is
 * actually missing (beyond10x/ess#221 adversary pass 1).
 */
function unreadIn(predicate: Predicate, row: Row): Unread {
  const source = facts(row);
  const read = paths(predicate);
  for (const path of read) {
    if (path.startsWith('input.') && !present(source, path)) {
      return { path, input: true, null: false };
    }
  }
  for (const path of read) {
    if (path.startsWith('input.') || present(source, path)) continue;
    return { path, input: false, null: source.has(path) };
  }
  return { path: read[0] ?? '', input: false, null: false };
}

/**
 * The first branch selected by the stored row that holds, in declaration order, or the decision a
 * branch the model cannot evaluate before it stands for. A branch after the one that holds is not
 * read, as `interpret::execute::select` stops at the first that holds.
 */
function heldBranch(
  command: Command,
  outcomes: Node[],
  record: Rec,
  source: FactSource,
  input: Row,
): { held?: Node; decision?: Decision } {
  for (const outcome of outcomes) {
    const row = command.rows.get(outcome.name);
    if (row === undefined) continue;
    const holds = rowHolds(command, String(outcome.name), row, record, source, input);
    if (typeof holds !== 'boolean') return { decision: holds };
    if (holds) return { held: outcome };
  }
  return {};
}

/**
 * The external branches of a command this input and subject make eligible, in declaration order,
 * or why an eligibility guard cannot be evaluated.
 */
function eligibleExternals(
  command: Command,
  outcomes: Node[],
  source: FactSource,
  record: Rec | undefined,
): Node[] | string {
  const externals: Node[] = [];
  for (const outcome of outcomes) {
    if (!isExternal(outcome)) continue;
    if (outcome.condition.kind === 'external_when') {
      const guard = command.guards.get(outcome.name) as Predicate;
      const truth = guard.evaluate(source);
      if (truth === TruthUnknown) {
        return `the guard of \`${outcome.name}\` (${guard}) is unknown over a generated input`;
      }
      if (truth !== TruthTrue) continue;
    }
    if (
      outcome.subject?.effect === 'moves' &&
      record !== undefined &&
      !list(outcome.subject.transition.from).includes(record.fields.state)
    ) {
      continue;
    }
    externals.push(outcome);
  }
  return externals;
}

/**
 * The branches a step may take: the ordinary one, unless an earlier arrangement of this command
 * may still hold and an external branch is eligible, then every eligible external branch the
 * target has not refused to arrange.
 */
interface Choice {
  arrangement: string;
  expected: Node;
}

function choices(
  s: Session,
  command: Command,
  decision: Decision & { kind: 'take' },
  input: Row,
): Choice[] {
  const out: Choice[] = [];
  if (
    decision.outcome !== undefined &&
    (!s.forced.has(command.name) || decision.externals.length === 0)
  ) {
    out.push({ arrangement: '', expected: decision.outcome });
  }
  for (const outcome of decision.externals) {
    if (!s.p.unarrangeable.has(`${command.name}/${outcome.name}`)) {
      out.push({
        arrangement: String(outcome.name),
        expected: terminal(command, outcome, input, s.model),
      });
    }
  }
  return out;
}

/** Asks the target to make `command` take the external branch `outcome`. */
async function arrange(
  s: Session,
  command: Command,
  outcome: string,
): Promise<Disagreement | null> {
  try {
    await s.target.configureExternalOutcome({
      command: command.name,
      outcome,
      correlation: s.correlation,
    });
  } catch (error) {
    if (isUnsupported(error)) throw new Unsupported(errorText(error));
    return {
      kind: 'target',
      detail: `arranging \`${outcome}\`, the target threw ${errorText(error)}`,
    };
  }
  s.forced.add(command.name);
  return null;
}

// ---- drawing inputs -----------------------------------------------------------------------------

/** One step of a trace. An input naming an existing record keeps it as (entity, creation index). */
interface Step {
  command: string;
  input: Row;
  refs: [string, string, number][];
  /** The external branch arranged for this step, or empty for the ordinary branch. */
  external: string;
  /** Identities deliberately absent in the serial draw/replay model. */
  fresh?: [string, string][];
}

const NO_RECORD = Symbol('no record');
const ABSENT = Symbol('absent');

function drawValue(
  kind: Kind,
  rng: Mulberry32,
  command: Command,
  model: Model,
  path: string,
  mustExist: boolean,
  refs: [string, string, number][],
): Node | typeof NO_RECORD {
  switch (kind.kind) {
    case 'optional':
      return rng.chance(0.5)
        ? ABSENT
        : drawValue(kind.base, rng, command, model, path, mustExist, refs);
    case 'identity': {
      const known = model.of(kind.entity);
      if (mustExist) {
        if (known.length === 0) return NO_RECORD;
        const index = rng.int(0, known.length - 1);
        refs.push([path, kind.entity, index]);
        return (known[index] as Rec).id;
      }
      if (known.length > 0 && rng.chance(0.8)) {
        const index = rng.int(0, known.length - 1);
        refs.push([path, kind.entity, index]);
        return (known[index] as Rec).id;
      }
      return drawValue(kind.base, rng, command, model, path, false, refs);
    }
    case 'integer':
    case 'decimal':
      return rng.chance(0.7) ? rng.pick(integersAt(command.pools, path)) : rng.int(-10, 10000);
    case 'boolean':
      return rng.chance(0.5);
    case 'string':
      return rng.pick(textsAt(command.pools, path));
    case 'timestamp': {
      // One seeded draw selects a UTC second on a fixed date, never a target clock.
      const second = rng.int(0, 86399);
      const part = (value: number): string => String(value).padStart(2, '0');
      return `2020-01-01T${part(Math.floor(second / 3600))}:${part(Math.floor(second / 60) % 60)}:${part(second % 60)}Z`;
    }
    case 'uuid':
      return `00000000-0000-4000-8000-${String(rng.int(0, 999999)).padStart(12, '0')}`;
    case 'enum':
      return rng.pick(enumsAt(command.pools, path, kind.variants));
    case 'struct': {
      const value: Row = {};
      for (const [name, field, presence] of kind.fields) {
        const drawn = drawValue(field, rng, command, model, `${path}.${name}`, false, refs);
        if (drawn === NO_RECORD) return NO_RECORD;
        if (drawn !== ABSENT) value[name] = drawn;
        else if (presence !== 'omitted_when_absent') value[name] = null;
      }
      return value;
    }
    default:
      return null;
  }
}

function draw(command: Command, rng: Mulberry32, model: Model): Step | null {
  const supplied = suppliedOutcome(command);
  const instance = supplied?.subject?.instance?.field?.name;
  // `created` is the input naming the identity an `existing_instance` branch is decided by, and
  // the entity it is looked up in (beyond10x/ess#221): drawn, as a supplied instance with an
  // unknown-instance branch is, to name a record or not with even chance.
  let created = '';
  let createdEntity = '';
  if (existingOutcome(command.node) !== undefined) {
    for (const address of addresses(command.node)) {
      if (address.field !== '') {
        created = address.field;
        createdEntity = address.entity;
      }
    }
  }
  const input: Row = {};
  const refs: [string, string, number][] = [];
  const fresh: [string, string][] = [];
  for (const [name, declared, presence] of command.inputs) {
    let kind = declared;
    if (name === instance && kind.kind !== 'identity') {
      kind = { kind: 'identity', entity: supplied.subject.entity, base: kind };
    }
    const probesUnknown = name === instance && unknownOutcome(command) !== undefined;
    let probed: string = probesUnknown ? supplied.subject.entity : '';
    if (name === created && !probesUnknown) {
      kind = {
        kind: 'identity',
        entity: createdEntity,
        base: kind.kind === 'identity' ? kind.base : kind,
      };
      probed = createdEntity;
    }
    let value: Node;
    if (probesUnknown || name === created) {
      const known = model.of(probed);
      if (known.length > 0 && rng.chance(0.5)) {
        value = drawValue(kind, rng, command, model, name, true, refs);
      } else {
        value = NO_RECORD;
        for (let attempt = 0; attempt < ATTEMPTS_PER_STEP; attempt += 1) {
          const drawn = drawValue(
            kind.kind === 'identity' ? kind.base : kind,
            rng,
            command,
            model,
            name,
            false,
            [],
          );
          if (drawn !== NO_RECORD && drawn !== ABSENT && model.find(probed, drawn) === undefined) {
            value = drawn;
            fresh.push([name, probed]);
            break;
          }
        }
      }
    } else {
      value = drawValue(kind, rng, command, model, name, name === instance, refs);
    }
    if (value === NO_RECORD) return null;
    if (value !== ABSENT) input[name] = value;
    else if (presence !== 'omitted_when_absent') input[name] = null;
  }
  return { command: command.name, input, refs, external: '', fresh };
}

// ---- one step against the target ----------------------------------------------------------------

interface Disagreement {
  kind: string;
  detail: string;
}

class Unsupported extends Error {}

interface Session {
  p: Plan;
  target: Target;
  model: Model;
  correlation: string;
  undetermined: Set<string>;
  /** Every command the target was asked to arrange a branch for in this sequence. */
  forced: Set<string>;
}

function render(value: Node): string {
  return value === undefined ? 'nothing' : goMarshal(value);
}

async function perform(
  s: Session,
  command: Command,
  step: Step,
  outcome: Node,
): Promise<Disagreement | null> {
  const ir = s.p.ir;
  let result: CommandResult;
  try {
    result = await s.target.executeCommand({
      command: command.name,
      actor: command.actor,
      input: step.input,
      correlation: s.correlation,
    });
  } catch (error) {
    if (isUnsupported(error)) throw new Unsupported(errorText(error));
    return { kind: 'target', detail: `the target threw ${errorText(error)}` };
  }
  const got = result.outcome ?? '';
  if (got !== outcome.name) {
    return {
      kind: 'outcome',
      detail: `the target answered \`${got}\`, the specification says \`${outcome.name}\``,
    };
  }
  const error = result.error ?? '';
  const wanted = typeof outcome.error === 'string' ? outcome.error : '';
  if (error !== wanted) {
    return {
      kind: 'error',
      detail: `the target refused with \`${error}\`, the specification says \`${wanted}\``,
    };
  }
  const events = result.directEvents ?? [];
  const names = events.map((event) => event.event).join(', ');
  const emits = list(outcome.emits).join(', ');
  if (names !== emits) {
    return {
      kind: 'events',
      detail: `the target emitted [${names}], the specification says [${emits}]`,
    };
  }
  for (const [index, event] of events.entries()) {
    const declared = list(outcome.payload).find((entry: Node) => entry.event === event.event);
    for (const field of list(declared?.fields)) {
      const expected = valueOf(ir, field.value, step.input, field.target_type);
      if (expected === undefined || expected === CLEARED) continue;
      const actual = (event.payload ?? {})[field.target];
      const target = list(ir.events[event.event]?.fields).find(
        (declared: Node) => declared.name === field.target,
      );
      if (
        !valueAgrees(
          ir,
          field.target_type,
          target?.naming,
          expected,
          actual,
          Object.prototype.hasOwnProperty.call(event.payload ?? {}, field.target),
        )
      ) {
        return {
          kind: 'payload',
          detail: `event ${index} \`${event.event}\`.${field.target} is ${render(actual)}, the specification says ${render(expected)}`,
        };
      }
    }
  }

  const subject = outcome.subject;
  if (subject !== null && subject !== undefined) {
    const entity = ir.entities[subject.entity];
    let record: Rec | undefined;
    if (subject.effect === 'creates') {
      const field = subject.instance.field.name;
      const carrier = events.find((event) => event.event === subject.instance.event);
      const id = carrier?.payload?.[field];
      if (id === undefined || id === null) {
        return {
          kind: 'identity',
          detail: `the target emitted no \`${subject.instance.event}\`.${field}`,
        };
      }
      if (s.model.find(subject.entity, id) !== undefined) {
        return {
          kind: 'identity',
          detail: `the target created ${render(id)} again, over an existing record`,
        };
      }
      // A creation lands in the state `into:` names (ess/15), or where the lifecycle starts.
      record = {
        id,
        fields: { [entity.identity.name]: id, state: subject.into ?? entity.lifecycle?.initial },
      };
      s.model.of(subject.entity).push(record);
    } else {
      record = s.model.find(subject.entity, readPath(step.input, subject.instance.field.name));
      if (record !== undefined && subject.effect === 'moves')
        record.fields.state = subject.transition.to;
    }
    if (record !== undefined) {
      for (const set of list(outcome.sets)) {
        const value = valueOf(ir, set.value, step.input, set.target_type);
        if (value === undefined) delete record.fields[set.target];
        else if (value === CLEARED) record.fields[set.target] = null;
        else record.fields[set.target] = value;
      }
    }
  }

  const views = await checkViews(s, result.consistency ?? '');
  if (views !== null) return views;
  return checkInvariants(s);
}

function agree(
  ir: Node,
  view: Node,
  identity: string,
  rows: Row[],
  expected: Rec[],
): Disagreement | null {
  if (rows.length !== expected.length) {
    return {
      kind: 'view-rows',
      detail: `\`${view.name}\` holds ${rows.length} row(s), the specification says ${expected.length}`,
    };
  }
  const fields = list(view.fields).map((field: Node) => String(field.name));
  if (fields.includes(identity)) {
    const seen = new Set<Rec>();
    for (const row of rows) {
      const record = expected.find((candidate) => equal(candidate.id, row[identity]));
      if (record === undefined || seen.has(record)) {
        return {
          kind: 'view-rows',
          detail: `\`${view.name}\` holds ${identity} ${render(row[identity])}, which the specification does not place there`,
        };
      }
      seen.add(record);
      for (const field of fields) {
        if (!Object.prototype.hasOwnProperty.call(record.fields, field)) continue;
        const declared = list(view.fields).find((entry: Node) => entry.name === field);
        if (
          !valueAgrees(
            ir,
            declared.type_ref,
            declared.naming,
            record.fields[field],
            row[field],
            Object.prototype.hasOwnProperty.call(row, field),
          )
        ) {
          return {
            kind: 'view-field',
            detail: `\`${view.name}\`.${field} of ${render(row[identity])} is ${render(row[field])}, the specification says ${render(record.fields[field])}`,
          };
        }
      }
    }
  }
  const orderBy = list(view.order_by).map(String);
  if (orderBy.length > 0) {
    const [ok, message] = ranked(view.name, orderBy, rows);
    if (!ok) return { kind: 'view-order', detail: message };
  }
  return null;
}

async function checkViews(s: Session, token: string): Promise<Disagreement | null> {
  const ir = s.p.ir;
  for (const view of [...s.p.views]) {
    const entity = ir.entities[view.source];
    const filter = view.filter === undefined || view.filter === null ? null : fromNode(view.filter);
    const expected: Rec[] = [];
    let placed = true;
    for (const record of s.model.of(entity.name)) {
      if (filter === null) {
        expected.push(record);
        continue;
      }
      const truth = filter.evaluate(facts(record.fields));
      if (truth === TruthUnknown) {
        s.undetermined.add(
          `${view.name} filter reads ${missing(filter, record.fields)}, which no command set`,
        );
        placed = false;
        break;
      }
      if (truth === TruthTrue) expected.push(record);
    }
    if (!placed) continue;

    const eventual = view.consistency !== 'read_your_writes';
    const attempts = eventual ? newHarness(s.p.system).deadline().attempts : 1;
    let problem: Disagreement | null = null;
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      let rows: Row[];
      try {
        const answer = await s.target.queryView({
          view: view.name,
          params: {},
          atLeast: eventual ? '' : token,
          correlation: s.correlation,
          deadline: { attempts: attempts - attempt },
        });
        rows = answer.rows ?? [];
      } catch (error) {
        if (isUnsupported(error)) {
          exclude(s.p, view.name, `the target does not expose it: ${errorText(error)}`);
          problem = null;
          break;
        }
        return {
          kind: 'target',
          detail: `reading \`${view.name}\`, the target threw ${errorText(error)}`,
        };
      }
      problem = agree(ir, view, String(entity.identity.name), rows, expected);
      if (problem === null) break;
    }
    if (problem !== null) return problem;
  }
  return null;
}

function checkInvariants(s: Session): Disagreement | null {
  for (const entity of sortedValues(s.p.ir.entities)) {
    for (const invariant of list(entity.invariants)) {
      const predicate = parsed(invariant);
      if (typeof predicate === 'string') continue;
      for (const record of s.model.of(entity.name)) {
        const truth = predicate.evaluate(facts(record.fields));
        if (truth === TruthFalse) {
          return {
            kind: 'specification',
            detail: `${entity.name} ${render(record.id)} breaks \`${predicate}\`: the guards allow a sequence the invariants forbid`,
          };
        }
        if (truth === TruthUnknown) {
          s.undetermined.add(
            `${entity.name} invariant \`${predicate}\` reads ${missing(predicate, record.fields)}, which no command set`,
          );
        }
      }
    }
  }
  return null;
}

// ---- sequences ----------------------------------------------------------------------------------

function line(step: Step): string {
  const external = step.external === '' ? '' : ` [external: ${step.external}]`;
  return `${step.command} ${goMarshal(step.input)}${external}`;
}

interface Found {
  kind: string;
  message: string;
  executed: Step[];
}

function describe(found: Disagreement, index: number, step: Step): string {
  return `${found.kind}: ${found.detail} (step ${index + 1}: ${line(step)})`;
}

async function open(
  p: Plan,
  newTarget: () => Answer<Target>,
  scenario: string,
): Promise<Session & { scenario: string }> {
  const target = await newTarget();
  const correlation = newHarness(p.system).correlation();
  await target.beginScenario({ scenario, correlation });
  const session = {
    p,
    target,
    model: new Model(),
    correlation,
    undetermined: new Set<string>(),
    forced: new Set<string>(),
    scenario,
  };
  await preconditions(session);
  return session;
}

/**
 * Runs the system's preconditions (ess/15) before a sequence, so the model starts from the state
 * they leave. A precondition the model or the target does not take is a setup failure, thrown, and
 * never a disagreement: the sequence has not started.
 */
async function preconditions(s: Session): Promise<void> {
  for (const pre of s.p.ir.preconditions ?? []) {
    const name = String(pre.command);
    if (nonEmpty(pre.fixtures)) {
      throw new Error(
        `precondition \`${name}\` reads fixture inputs, which exploration does not resolve`,
      );
    }
    const planned =
      s.p.commands.find((candidate) => candidate.name === name) ?? s.p.sendable.get(name);
    if (planned === undefined) {
      throw new Error(`precondition \`${name}\` is a command exploration excludes`);
    }
    const command: Command = { ...planned, actor: pre.actor ?? planned.actor };
    const input: Row = { ...(pre.input ?? {}) };
    const step: Step = { command: name, input, refs: [], external: '' };
    const decision = decide(command, input, s.model);
    // The model must take the branch the specification requires of it, as synthesis does: a
    // precondition the model decides as a refusal, or as anything else, fails as setup.
    const wanted = String(pre.outcome);
    if (
      decision.kind !== 'take' ||
      decision.outcome === undefined ||
      decision.outcome === null ||
      String(decision.outcome.name) !== wanted
    ) {
      throw new Error(
        `precondition \`${name}\` failed as setup: the model does not take \`${wanted}\``,
      );
    }
    const found = await perform(s, command, step, decision.outcome);
    if (found !== null) {
      throw new Error(`precondition \`${name}\` failed as setup: ${found.kind}: ${found.detail}`);
    }
  }
}

/** Replays `trace` on a fresh target: the disagreement it ends in, or null when it passes. */
async function replay(
  p: Plan,
  newTarget: () => Answer<Target>,
  trace: Step[],
  scenario: string,
): Promise<Found | null> {
  const s = await open(p, newTarget, scenario);
  const executed: Step[] = [];
  try {
    for (const recorded of trace) {
      const command = p.commands.find((candidate) => candidate.name === recorded.command);
      if (command === undefined) continue;
      const input = JSON.parse(JSON.stringify(recorded.input)) as Row;
      let resolvable = true;
      for (const [path, entity, index] of recorded.refs) {
        const known = s.model.of(entity);
        if (index >= known.length) resolvable = false;
        else setPath(input, path, (known[index] as Rec).id);
      }
      if (!resolvable) continue;
      if (
        (recorded.fresh ?? []).some(
          ([path, entity]) => s.model.find(entity, readPath(input, path)) !== undefined,
        )
      )
        continue;
      const step: Step = {
        command: recorded.command,
        input,
        refs: recorded.refs,
        external: recorded.external,
        fresh: recorded.fresh ?? [],
      };
      const decision = decide(command, input, s.model);
      if (decision.kind !== 'take') continue;
      const outcome = choices(s, command, decision, input).find(
        (choice) => choice.arrangement === step.external,
      );
      if (outcome === undefined) continue;
      let found: Disagreement | null;
      try {
        if (step.external !== '') {
          const arranging = await arrange(s, command, step.external);
          if (arranging !== null) {
            executed.push(step);
            return {
              kind: arranging.kind,
              message: describe(arranging, executed.length - 1, step),
              executed,
            };
          }
        }
        found = await perform(s, command, step, outcome.expected);
      } catch (error) {
        if (error instanceof Unsupported) continue;
        throw error;
      }
      executed.push(step);
      if (found !== null) {
        return { kind: found.kind, message: describe(found, executed.length - 1, step), executed };
      }
    }
    return null;
  } finally {
    await s.target.endScenario({ scenario: s.scenario, correlation: s.correlation });
  }
}

/**
 * explore runs `seeds` sequences of `steps` random commands, each on a fresh target, and checks
 * every step against the model interpreted from `ir.json`. It stops at the first disagreement and
 * shrinks it.
 *
 * Throws only when the model cannot be used: an absent or unreadable `ir.json`, or one that is not
 * the model `suite.json` was synthesized from. A disagreement is the result's `failure`.
 */
export async function explore(
  newTarget: () => Answer<Target>,
  options: ExploreOptions = {},
): Promise<ExploreResult> {
  const p = plan(loadModel());
  const steps = options.steps ?? DEFAULT_STEPS;
  const seeds: number[] = [];
  if (options.seed !== undefined) seeds.push(options.seed);
  else for (let seed = 1; seed <= (options.seeds ?? DEFAULT_SEEDS); seed += 1) seeds.push(seed);

  const reached = new Set<string>();
  const ambiguous = new Set<string>();
  const undetermined = new Set<string>();
  let executed = 0;
  let sequences = 0;
  let failure: ExploreFailure | undefined;

  for (const seed of seeds) {
    if (p.commands.length === 0 || failure !== undefined) break;
    sequences += 1;
    const rng = new Mulberry32(seed);
    const s = await open(p, newTarget, `explore/seed-${seed}`);
    s.undetermined = undetermined;
    const trace: Step[] = [];
    let found: Found | null = null;
    try {
      for (
        let attempts = 0;
        trace.length < steps && attempts < steps * ATTEMPTS_PER_STEP;
        attempts += 1
      ) {
        if (p.commands.length === 0) break;
        const command = rng.pick(p.commands);
        const step = draw(command, rng, s.model);
        if (step === null) continue;
        const decision = decide(command, step.input, s.model);
        if (decision.kind === 'ambiguous') {
          ambiguous.add(`${command.name}: ${decision.names.join(', ')}`);
          continue;
        }
        if (decision.kind === 'unknown') {
          exclude(p, command.name, decision.reason);
          continue;
        }
        if (decision.kind === 'undetermined') {
          undetermined.add(decision.reason);
          continue;
        }
        const available = choices(s, command, decision, step.input);
        if (available.length === 0) {
          if (decision.names !== undefined) {
            ambiguous.add(`${command.name}: ${decision.names.join(', ')}`);
          }
          continue;
        }
        const outcome = available.length > 1 ? rng.pick(available) : (available[0] as Choice);
        if (outcome.arrangement !== '') {
          step.external = outcome.arrangement;
          let arranging: Disagreement | null;
          try {
            arranging = await arrange(s, command, step.external);
          } catch (error) {
            if (error instanceof Unsupported) {
              p.unarrangeable.set(
                `${command.name}/${step.external}`,
                `the target cannot arrange it: ${error.message}`,
              );
              continue;
            }
            throw error;
          }
          if (arranging !== null) {
            trace.push(step);
            found = {
              kind: arranging.kind,
              message: describe(arranging, trace.length - 1, step),
              executed: [...trace],
            };
            break;
          }
        }
        let disagreement: Disagreement | null;
        try {
          disagreement = await perform(s, command, step, outcome.expected);
        } catch (error) {
          if (error instanceof Unsupported) {
            exclude(p, command.name, `the target does not expose it: ${error.message}`);
            continue;
          }
          throw error;
        }
        executed += 1;
        trace.push(step);
        reached.add(`${command.name}/${outcome.expected.name}`);
        if (disagreement !== null) {
          found = {
            kind: disagreement.kind,
            message: describe(disagreement, trace.length - 1, step),
            executed: [...trace],
          };
          break;
        }
      }
    } finally {
      await s.target.endScenario({ scenario: s.scenario, correlation: s.correlation });
    }
    if (found !== null) failure = await shrink(p, newTarget, seed, trace, found);
  }

  const unreached: string[] = [];
  const excludedOutcomes: string[] = [];
  for (const [command, outcomes] of p.declared) {
    for (const outcome of outcomes) {
      const id = `${command}/${outcome}`;
      if (p.excludedCommands.has(command)) excludedOutcomes.push(id);
      else if (!reached.has(id) && !p.unarrangeable.has(id)) unreached.push(id);
    }
  }
  const external: ExternalReach[] = p.externals
    .map(({ command, id, cause }): ExternalReach => {
      const reason = p.unarrangeable.get(id);
      if (p.excludedCommands.has(command)) return { outcome: id, cause, reach: 'excluded' };
      if (reached.has(id)) return { outcome: id, cause, reach: 'reached' };
      if (reason !== undefined) return { outcome: id, cause, reach: 'unarrangeable', reason };
      return { outcome: id, cause, reach: 'unreached' };
    })
    .sort((left, right) => byteCompare(left.outcome, right.outcome));
  const result: ExploreResult = {
    sequences,
    steps,
    executed,
    reached: sortStrings([...reached]),
    unreached: sortStrings(unreached),
    excluded: [...p.excluded].sort(
      (left, right) =>
        byteCompare(left.subject, right.subject) || byteCompare(left.reason, right.reason),
    ),
    excludedOutcomes: sortStrings(excludedOutcomes),
    undetermined: sortStrings([...undetermined]),
    ambiguous: sortStrings([...ambiguous]),
  };
  if (external.length > 0) result.external = external;
  if (failure !== undefined) result.failure = failure;
  return result;
}

/** Keep the Optional/identity witness and arranged cause when accepting a shorter failure. */
function sameFailure(p: Plan, original: Found, replayed: Found): boolean {
  if (original.kind !== replayed.kind) return false;
  const last = original.executed[original.executed.length - 1];
  const next = replayed.executed[replayed.executed.length - 1];
  const command = p.commands.find((candidate) => candidate.name === last?.command);
  const optional = (kind: Kind): boolean =>
    kind.kind === 'optional' ||
    (kind.kind === 'struct' && kind.fields.some(([, member]) => optional(member))) ||
    (kind.kind === 'identity' && optional(kind.base));
  if (
    command === undefined ||
    (unknownOutcome(command) === undefined &&
      existingOutcome(command.node) === undefined &&
      !command.inputs.some(([, kind]) => optional(kind)))
  )
    return true;
  return (
    last?.command === next?.command &&
    last?.external === next?.external &&
    equal(last?.fresh ?? [], next?.fresh ?? []) &&
    original.message.split(' (step ')[0] === replayed.message.split(' (step ')[0]
  );
}

/** Removes one step at a time, last to first, while the shorter trace still fails the same way. */
async function shrink(
  p: Plan,
  newTarget: () => Answer<Target>,
  seed: number,
  trace: Step[],
  found: Found,
): Promise<ExploreFailure> {
  let current = trace;
  let shortest = found;
  let replays = 0;
  let complete = true;
  for (let removed = true; removed; ) {
    removed = false;
    for (let index = current.length - 1; index >= 0; index -= 1) {
      if (replays >= SHRINK_REPLAYS) {
        complete = false;
        break;
      }
      const candidate = current.filter((_, position) => position !== index);
      replays += 1;
      const again = await replay(p, newTarget, candidate, `explore/seed-${seed}/shrink-${replays}`);
      if (again !== null && sameFailure(p, found, again)) {
        current = candidate;
        shortest = again;
        removed = true;
      }
    }
    if (!complete) break;
  }
  return {
    seed,
    message: shortest.message,
    trace: shortest.executed.map(line),
    originalLength: trace.length,
    shrinkComplete: complete,
  };
}

/** What `assertExplored` would fail with, or null when it passes. */
export function exploreProblem(result: ExploreResult, options: AssertOptions = {}): string | null {
  const problems: string[] = [];
  if (result.failure !== undefined) {
    const failure = result.failure;
    problems.push(
      `explore: seed ${failure.seed}: ${failure.message}\n` +
        `shrunk trace (${failure.trace.length} of ${failure.originalLength} step(s)${failure.shrinkComplete ? '' : ', not minimal'}):\n` +
        failure.trace.map((step) => `  ${step}`).join('\n'),
    );
  }
  if (result.unreached.length > 0) {
    problems.push(
      `explore: ${result.unreached.length} declared outcome(s) no sequence reached:\n` +
        result.unreached.map((outcome) => `  ${outcome}`).join('\n'),
    );
  }
  if (result.excludedOutcomes.length > 0 && options.allowExcluded !== true) {
    problems.push(
      `explore: ${result.excludedOutcomes.length} declared outcome(s) of excluded commands were never tried:\n` +
        result.excludedOutcomes.map((outcome) => `  ${outcome}`).join('\n') +
        '\nexcluded:\n' +
        result.excluded
          .map((exclusion) => `  ${exclusion.subject}: ${exclusion.reason}`)
          .join('\n') +
        '\naccept them explicitly with { allowExcluded: true }',
    );
  }
  const unarrangeable = (result.external ?? []).filter(
    (branch) => branch.reach === 'unarrangeable',
  );
  if (unarrangeable.length > 0 && options.allowExcluded !== true) {
    problems.push(
      `explore: ${unarrangeable.length} external outcome(s) the target could not arrange were never tried:\n` +
        unarrangeable.map((branch) => `  ${branch.outcome}: ${branch.reason ?? ''}`).join('\n') +
        '\naccept them explicitly with { allowExcluded: true }',
    );
  }
  return problems.length === 0 ? null : problems.join('\n');
}

/**
 * assertExplored throws when an exploration failed, when a declared outcome went unreached, or
 * when an excluded command's outcomes, or external outcomes the target could not arrange, were
 * never tried and `allowExcluded` is not set. What the
 * model could not place, and the draws it would not decide, are printed and do not fail.
 */
export function assertExplored(result: ExploreResult, options: AssertOptions = {}): void {
  for (const note of result.undetermined) console.log(`explore: undetermined: ${note}`);
  for (const note of result.ambiguous) console.log(`explore: ambiguous: ${note}`);
  const problem = exploreProblem(result, options);
  if (problem !== null) throw new Error(problem);
}

// ---- concurrent histories -----------------------------------------------------------------------
//
// `exploreConcurrent` drives the target from two to four clients at once and writes what each call
// did as an `ess-history/1` document, one per seed. It does not decide whether a history is
// linearizable: it runs `ess verify conform check-history` on each one and reports that verdict,
// and for a violation the checker's report with its shrunk history. The checker, the model and the
// shrinking exist once, in the `ess` binary that emitted this package, so `ess` must be on PATH;
// without it concurrent exploration fails, and is never skipped.
//
// Nothing races on a wall clock or on the event loop. A seed draws the workload — a sequential
// prefix of creations on client 0, then a list of calls per client — and a second generator,
// SplitMix64 as `ess` records with, picks at every tick of a logical clock which client acts next:
// one with no call in flight invokes its next call, or one with a call in flight receives its
// answer. Each move is awaited before the next is drawn, so one seed writes one history, byte for
// byte, and the Go port writes the same bytes.
//
// A client's call may be a read of one of the specification's views, drawn from the seed beside the
// commands. A client keeps the consistency token its own last answered command returned, and a read
// of a `read_your_writes` view demands it (`atLeast`); a read of an `eventual` view demands none.
// The view is asked at the read's return instant, and what it answered is written as `rows`: the
// identity of each row, in the order answered, read off the field that carries the identity of the
// entity the view projects. A read's `outcome` is `read` and its `subject_key` is empty. A read is
// written without `rows`, which `ess` lists as not judged, when one of its rows does not carry that
// identity as text. For each creation of that entity invoked before the read returned that never
// answered, one row no written operation names is left out of `rows`, the first in answer order:
// it may be what that creation made, which the checker could only read as shown before anyone
// asked for it. Every other row is written and judged.
//
// With `inject`, every fault the specification declares is injected, and no other: a second
// delivery for each `delivery: at_least_once` binding, a client retry for each command declaring
// `replays:`, and a delayed or unanswered answer for each command declaring another `external:`
// branch. Each is a move the seed schedules, drawn from its own SplitMix64 sequence of the seed,
// and `ConcurrentResult.injected` counts them and the declared branches they reached.

/** One call between its invoke and its return. */
export interface PendingCommand {
  /**
   * The answer arriving. A throw that `isIndeterminate` recognises is a call whose outcome is
   * unknown: it is written `Indeterminate`, because it may still have taken effect. An `unsupported`
   * throw leaves the call out of the history and the command in `excluded`. Anything else thrown
   * fails the exploration. A throw from `invokeCommand` is read the same way.
   */
  complete(): Answer<CommandResult>;
}

/**
 * A target whose calls have an invoke and a return with other clients' calls in between. A target
 * without `invokeCommand` does all of a call's work at its return instant, which is what an atomic
 * call is.
 */
export interface InterleavedTarget extends Target {
  invokeCommand(request: CommandRequest): Answer<PendingCommand>;
}

/** What one concurrent exploration is asked to do. */
export interface ConcurrentOptions {
  /** The specification `ess` checks each history against, as `--path` takes it. */
  path?: string;
  /** The directory each history is written into, as `history-<seed>.json`. */
  out?: string;
  /** Histories to record, seeded `1…seeds`. Default 200. */
  seeds?: number;
  /** Record exactly this one history, overriding `seeds`. */
  seed?: number;
  /** How many clients call at once, 2 to 4. Default: drawn from each seed. */
  clients?: number;
  /** How many calls each client makes after the prefix. Default 3. */
  calls?: number;
  /**
   * Accept commands the target does not expose (it threw `unsupported`), whose calls are then not
   * written to any history. An explicit, reviewable opt-out, as `assertExplored` has.
   */
  allowExcluded?: boolean;
  /**
   * Inject every fault the specification declares, and no other, each as one more move the seed
   * schedules: a second delivery of an event only `delivery: at_least_once` bindings react to
   * (`redeliverEvent`); the same request sent again, as a second operation whose `retry_of` names
   * the first, for a command declaring `replays:`; and, for a command declaring another `external:`
   * branch, an answer delayed past the client's wait or never arriving, written `Indeterminate`.
   * Nothing is injected into the prefix. `ess` records the same way.
   */
  inject?: boolean;
}

/** What an exploration injected, keyed by what declared each fault. */
export interface ConcurrentInjected {
  /** Second deliveries, by the binding declaring `at_least_once`. */
  redeliveries: Record<string, number>;
  /** Second deliveries the target refused, by event. */
  refused: Record<string, number>;
  /** Requests sent again, by the command declaring `replays:`. */
  retries: Record<string, number>;
  /** Calls answered after the client stopped waiting, by command. */
  delayed: Record<string, number>;
  /** Calls never answered and never executed, by command. */
  unanswered: Record<string, number>;
  /** The declared branch each retried or delayed call's answer took, as `command/outcome`. */
  reached: Record<string, number>;
}

/** The first history `ess` did not find linearizable. */
export interface ConcurrentFailure {
  seed: number;
  /** `Violation` or `Unknown`. */
  verdict: string;
  /** The file it was written to, inside `out`. */
  history: string;
  /**
   * What `ess verify conform check-history` printed: for a violation, the longest partial
   * linearization and the shrunk history.
   */
  report: string;
}

/** What a concurrent exploration found. */
export interface ConcurrentResult {
  histories: number;
  linearizable: number;
  violations: number;
  unknown: number;
  /** The calls, across every history, that never answered and were written `Indeterminate`. */
  indeterminate: number;
  /**
   * Every command or view the target threw `unsupported` for, and why, in the order found. It is
   * still drawn in every seed, so a seed's history does not depend on the seeds before it, but its
   * calls are not written.
   */
  excluded: Exclusion[];
  /** `allowExcluded` from the options, so `concurrentProblem` can read it. */
  allowExcluded: boolean;
  /** Each history's verdict, in seed order. */
  verdicts: string[];
  failure?: ConcurrentFailure;
  /** What was injected across every history, all empty without `inject`. */
  injected: ConcurrentInjected;
}

/** The refusal when `ess` is not on PATH. */
export const NO_ESS =
  'explore: concurrent exploration checks every history with `ess verify conform check-history`, and `ess` is not on PATH';

const INDETERMINATE = Symbol.for('ess.conformance.indeterminate');

/**
 * What a target throws, or names as the `cause` of what it throws, for a call whose outcome it cannot
 * know: it timed out, or the connection dropped after the request left. The call is written
 * `Indeterminate`, because it may still have taken effect. An error named `TimeoutError` (what
 * `AbortSignal.timeout` rejects with) is read the same way. Anything else thrown fails the
 * exploration: a call that failed is not a call that may have succeeded.
 */
export function indeterminate(reason: string): Error {
  return Object.assign(new Error(reason), { [INDETERMINATE]: true });
}

/**
 * True for an error `indeterminate` made, a `TimeoutError`, or one that holds either through its
 * `cause` or, for an `AggregateError`, among its `errors`: the tree Go's `errors.Is` walks through
 * `%w` and `errors.Join`.
 */
export function isIndeterminate(error: unknown): boolean {
  const pending: unknown[] = [error];
  for (let visited = 0; pending.length > 0 && visited < 256; visited += 1) {
    const current = pending.shift();
    if (current === null || typeof current !== 'object') continue;
    if ((current as Record<symbol, unknown>)[INDETERMINATE] === true) return true;
    if ((current as { name?: unknown }).name === 'TimeoutError') return true;
    pending.push((current as { cause?: unknown }).cause);
    const errors = (current as { errors?: unknown }).errors;
    if (Array.isArray(errors)) pending.push(...errors);
  }
  return false;
}

export const DEFAULT_CONCURRENT_SEEDS = 200;
const CONCURRENT_CALLS = 3;
const CONCURRENT_PREFIX = 2;
const UNDECLARED = '<undeclared>';
const MASK_64 = (1n << 64n) - 1n;

/** The generator that picks which client acts next, as `ess` records with. */
export class SplitMix64 {
  private state: bigint;

  constructor(seed: number | bigint) {
    this.state = BigInt(seed) & MASK_64;
  }

  next(): bigint {
    this.state = (this.state + 0x9e3779b97f4a7c15n) & MASK_64;
    let z = this.state;
    z = ((z ^ (z >> 30n)) * 0xbf58476d1ce4e5b9n) & MASK_64;
    z = ((z ^ (z >> 27n)) * 0x94d049bb133111ebn) & MASK_64;
    return z ^ (z >> 31n);
  }

  below(bound: number): number {
    return Number(this.next() % BigInt(bound));
  }
}

interface Operation {
  client: number;
  command: string;
  subjectKey: string;
  invokedAt: number;
  returnedAt?: number;
  outcome?: string;
  /** A call the target does not expose: it is not written. */
  dropped?: boolean;
  /** One more than the index of the operation this one sends again, or 0. */
  retryOf: number;
  /** The entity a command's creating branch creates, or empty. */
  creates: string;
  /** The entity a read's view projects, or empty for a command. */
  source: string;
  /** What a returned read answered, each row's identity; absent where it records none. */
  rows?: string[];
}

interface Flight {
  pending: PendingCommand | null;
  command: Command | null;
  index: number;
  client: number;
  /** An injected delay (`DELAYED`) or loss (`UNANSWERED`), or 0. */
  timeout: number;
  /** The request of a read, which is sent at the return instant; null for a command. */
  read: ViewRequest | null;
  /** The field a read's rows carry their identity in. */
  identity: string;
}

/** One call of a client's workload: a command, or a read of `view`. */
type Call =
  | { command: Command; step: Step; view: null }
  | { command: null; step: null; view: Node };

/** A client's retry of the call it invoked last: waiting to be sent, then in flight. */
interface Retry {
  command: Command;
  step: Step;
  request: CommandRequest;
  original: number;
  flight: Flight | null;
}

/** An event waiting to be delivered a second time, and the bindings it reaches. */
interface Redelivery {
  event: string;
  bindings: string[];
}

interface Recording {
  target: Target;
  correlation: string;
  clock: number;
  operations: Operation[];
  /** The calls written `Indeterminate`. */
  indeterminate: number;
  /** Every command the target threw `unsupported` for, with its reason, in the order found. */
  unsupported: Exclusion[];
  /** The model, for what each binding and command declares. */
  ir: Node;
  /** Draws the injected faults; null when nothing is injected. */
  injection: SplitMix64 | null;
  /** True while the prefix runs, when nothing is injected into a call. */
  arranging: boolean;
  redeliveries: Redelivery[];
  retries: (Retry | null)[];
  injected: ConcurrentInjected;
  /** Each client's last consistency token, empty until one of its commands answers one. */
  tokens: string[];
}

/** Moves the injections' SplitMix64 sequence away from the schedule's, as `ess` does. */
const INJECTION_STREAM = 0x1f83d9abfb41bd6bn;
const DELAYED = 1;
const UNANSWERED = 2;

function newInjected(): ConcurrentInjected {
  return { redeliveries: {}, refused: {}, retries: {}, delayed: {}, unanswered: {}, reached: {} };
}

function bump(counts: Record<string, number>, key: string): void {
  counts[key] = (counts[key] ?? 0) + 1;
}

function addInjected(into: ConcurrentInjected, more: ConcurrentInjected): void {
  for (const kind of [
    'redeliveries',
    'refused',
    'retries',
    'delayed',
    'unanswered',
    'reached',
  ] as const) {
    for (const [key, count] of Object.entries(more[kind])) {
      into[kind][key] = (into[kind][key] ?? 0) + count;
    }
  }
}

/** An identity as a subject key: its text, or empty when it is not text. */
function subjectKey(value: Node): string {
  return typeof value === 'string' ? value : '';
}

/** Whether a command declares a `replays:` branch. */
function declaresReplay(command: Command): boolean {
  return list(command.node.outcomes).some(
    (outcome: Node) => outcome.replays !== undefined && outcome.replays !== null,
  );
}

/** Whether a command declares an `external:` branch other than a `replays:` one. */
function declaresOtherExternal(command: Command): boolean {
  return list(command.node.outcomes).some(
    (outcome: Node) =>
      (outcome.replays === undefined || outcome.replays === null) && isExternal(outcome),
  );
}

function requestOf(h: Recording, command: Command, step: Step): CommandRequest {
  return {
    command: command.name,
    actor: command.actor,
    input: step.input,
    correlation: h.correlation,
  };
}

function reserve(h: Recording, client: number, command: Command, step: Step): number {
  let subject = '';
  const supplied = suppliedOutcome(command);
  if (supplied !== undefined) {
    subject = subjectKey(readPath(step.input, String(supplied.subject?.instance?.field?.name)));
  }
  let creates = '';
  for (const outcome of list(command.node.outcomes)) {
    if (outcome.subject?.effect === 'creates') creates = String(outcome.subject.entity);
  }
  h.clock += 1;
  const index = h.operations.length;
  h.operations.push({
    client,
    command: command.name,
    subjectKey: subject,
    invokedAt: h.clock,
    retryOf: 0,
    creates,
    source: '',
  });
  return index;
}

/**
 * Reserves a read of `view`: its request demands the client's last token where the view is
 * `read_your_writes`, and is sent when the read returns.
 */
function invokeRead(h: Recording, client: number, view: Node): Flight {
  const name = String(view.name);
  const entity = h.ir.entities?.[view.source] ?? {};
  const atLeast = view.consistency === 'read_your_writes' ? (h.tokens[client] as string) : '';
  h.clock += 1;
  const index = h.operations.length;
  h.operations.push({
    client,
    command: name,
    subjectKey: '',
    invokedAt: h.clock,
    retryOf: 0,
    creates: '',
    source: String(entity.name ?? ''),
  });
  const read: ViewRequest = {
    view: name,
    params: {},
    atLeast,
    correlation: `${h.correlation}-${index + 1}`,
    deadline: { attempts: 1 },
  };
  return {
    pending: null,
    command: null,
    index,
    client,
    timeout: 0,
    read,
    identity: String(entity.identity?.name ?? ''),
  };
}

/** Asks the view, at the read's return instant, and writes what it answered. */
async function completeRead(h: Recording, flight: Flight): Promise<void> {
  const operation = h.operations[flight.index] as Operation;
  let rows: Row[];
  try {
    rows = (await h.target.queryView(flight.read as ViewRequest)).rows ?? [];
  } catch (error) {
    h.clock += 1;
    if (isUnsupported(error)) {
      operation.dropped = true;
      if (!h.unsupported.some((known) => known.subject === operation.command)) {
        h.unsupported.push({
          subject: operation.command,
          reason: `the target does not expose it: ${errorText(error)}`,
        });
      }
      return;
    }
    if (isIndeterminate(error)) {
      h.indeterminate += 1;
      return;
    }
    throw new Error(`reading \`${operation.command}\` failed: ${errorText(error)}`);
  }
  h.clock += 1;
  operation.returnedAt = h.clock;
  operation.outcome = 'read';
  const ids: string[] = [];
  for (const row of rows) {
    const id = row[flight.identity];
    if (typeof id !== 'string') return;
    ids.push(id);
  }
  operation.rows = ids;
}

/**
 * The rows a read is written with: every row it answered, in order, less one row no written
 * operation names for each creation of the view's entity that was invoked before the read returned
 * and never answered. Such a row may be the instance that creation made, which the checker could
 * only read as shown before anyone asked for it; the first such rows in answer order are the ones
 * left out. A named row is always written, and an unnamed row no unanswered creation can account
 * for is written and is the future read it looks like.
 */
function writtenRows(read: Operation, subjects: Set<string>, kept: Operation[]): string[] {
  let lost = kept.filter(
    (operation) =>
      operation.returnedAt === undefined &&
      operation.subjectKey === '' &&
      operation.creates === read.source &&
      operation.invokedAt < (read.returnedAt as number),
  ).length;
  const written: string[] = [];
  for (const row of read.rows ?? []) {
    if (!subjects.has(row) && lost > 0) {
      lost -= 1;
      continue;
    }
    written.push(row);
  }
  return written;
}

async function send(h: Recording, request: CommandRequest): Promise<PendingCommand> {
  const target = h.target as Partial<InterleavedTarget> & Target;
  if (typeof target.invokeCommand === 'function') {
    try {
      return await target.invokeCommand(request);
    } catch (error) {
      // Classified where the answer would have arrived, exactly as a throw from `complete` is.
      return {
        complete: () => {
          throw error;
        },
      };
    }
  }
  return { complete: () => target.executeCommand(request) };
}

async function invokeCall(
  h: Recording,
  client: number,
  command: Command,
  step: Step,
): Promise<Flight> {
  const request = requestOf(h, command, step);
  const index = reserve(h, client, command, step);
  // One call, one correlation: a retry sends it again under the same one, and a target tells a
  // retry from a new call of the same input only by it — it never replays one call for another.
  request.correlation = `${h.correlation}-${index + 1}`;
  let timeout = 0;
  if (h.injection !== null && !h.arranging) {
    if (h.retries[client] === null && declaresReplay(command)) {
      h.retries[client] = { command, step, request, original: index, flight: null };
    }
    if (declaresOtherExternal(command)) {
      const drawn = h.injection.below(3);
      if (drawn === 1) timeout = DELAYED;
      if (drawn === 2) timeout = UNANSWERED;
    }
  }
  return {
    pending: await send(h, request),
    command,
    index,
    client,
    timeout,
    read: null,
    identity: '',
  };
}

/** Sends a client's retry: the request it sent, unchanged, as a new operation. */
async function invokeRetry(h: Recording, client: number, retry: Retry): Promise<Flight> {
  const request = retry.request;
  const index = reserve(h, client, retry.command, retry.step);
  (h.operations[index] as Operation).retryOf = retry.original + 1;
  bump(h.injected.retries, retry.command.name);
  return {
    pending: await send(h, request),
    command: retry.command,
    index,
    client,
    timeout: 0,
    read: null,
    identity: '',
  };
}

/**
 * Queues a second delivery of every event `result` published that only `at_least_once` bindings
 * react to.
 */
function queueRedeliveries(h: Recording, result: CommandResult): void {
  if (h.injection === null) return;
  for (const event of result.directEvents ?? []) {
    const bindings: string[] = [];
    let declared = true;
    for (const binding of sortedValues(h.ir.bindings)) {
      if (typeof binding.event !== 'string' || binding.event !== event.event) continue;
      bindings.push(String(binding.name));
      declared = declared && binding.delivery === 'at_least_once';
    }
    if (bindings.length > 0 && declared) h.redeliveries.push({ event: event.event, bindings });
  }
}

/** Delivers the queued event at `slot` a second time. */
async function redeliver(h: Recording, slot: number): Promise<void> {
  const [queued] = h.redeliveries.splice(slot, 1) as [Redelivery];
  try {
    await h.target.redeliverEvent({ event: queued.event, correlation: h.correlation });
  } catch {
    bump(h.injected.refused, queued.event);
    return;
  }
  for (const binding of queued.bindings) bump(h.injected.redeliveries, binding);
}

/** The identity a creating branch of `command` published in `result`, and its entity, or null. */
function createdBy(command: Command, result: CommandResult): { id: string; entity: string } | null {
  const taken = result.outcome ?? '';
  for (const outcome of list(command.node.outcomes)) {
    if (String(outcome.name) !== taken) continue;
    const subject = outcome.subject;
    if (subject?.effect !== 'creates') return null;
    const carrier = subject.instance?.event;
    const field = subject.instance?.field?.name;
    for (const event of result.directEvents ?? []) {
      if (event.event !== carrier) continue;
      const id = subjectKey(event.payload?.[field]);
      if (id === '') return null;
      return { id, entity: String(subject.entity) };
    }
    return null;
  }
  return null;
}

/**
 * Writes the answer into the operation `flight` reserved, and returns the identity a creating
 * branch published and its entity, or null.
 */
async function completeCall(
  h: Recording,
  flight: Flight,
): Promise<{ id: string; entity: string } | null> {
  if (flight.read !== null) {
    await completeRead(h, flight);
    return null;
  }
  const command = flight.command as Command;
  const pending = flight.pending as PendingCommand;
  if (flight.timeout === UNANSWERED) {
    // The client stops waiting, and the target never executes the call.
    h.clock += 1;
    h.indeterminate += 1;
    bump(h.injected.unanswered, command.name);
    return null;
  }
  let result: CommandResult;
  try {
    result = await pending.complete();
  } catch (error) {
    h.clock += 1;
    const operation = h.operations[flight.index] as Operation;
    if (isUnsupported(error)) {
      operation.dropped = true;
      if (!h.unsupported.some((known) => known.subject === command.name)) {
        h.unsupported.push({
          subject: command.name,
          reason: `the target does not expose it: ${errorText(error)}`,
        });
      }
      return null;
    }
    if (isIndeterminate(error)) {
      h.indeterminate += 1;
      return null;
    }
    throw new Error(`\`${command.name}\` failed: ${errorText(error)}`);
  }
  h.clock += 1;
  const operation = h.operations[flight.index] as Operation;
  const taken = result.outcome ?? '';
  queueRedeliveries(h, result);
  const created = createdBy(command, result);
  if (flight.timeout === DELAYED) {
    // Executed, and answered after the client stopped waiting: written `Indeterminate`, with the
    // instance the late answer named, so a read showing it is not a read of nothing.
    h.indeterminate += 1;
    bump(h.injected.delayed, command.name);
    bump(h.injected.reached, `${command.name}/${taken}`);
    if (operation.subjectKey === '' && created !== null) operation.subjectKey = created.id;
    return null;
  }
  if (operation.retryOf !== 0) bump(h.injected.reached, `${command.name}/${taken}`);
  if (typeof result.consistency === 'string' && result.consistency !== '') {
    h.tokens[flight.client] = result.consistency;
  }
  operation.returnedAt = h.clock;
  operation.outcome = taken === '' ? UNDECLARED : taken;
  if (created === null) return null;
  if (operation.subjectKey === '') operation.subjectKey = created.id;
  return created;
}

function uuidOf(n: bigint): string {
  return `00000000-0000-4000-8000-${n.toString(16).padStart(12, '0')}`;
}

/** A JSON string as `ess` writes one: no HTML escaping. */
function quote(text: string): string {
  return goMarshal(text, false);
}

/** A JSON object of `members`, in the order given, each value already written. */
function jsonObject(members: [string, string][]): string {
  return `{${members.map(([key, value]) => `${quote(key)}:${value}`).join(',')}}`;
}

/**
 * The history in the one spelling `ess` reads and writes: compact, keys in declaration order, an
 * absent `returned_at` and `outcome` for a call that never answered.
 */
function historyText(
  digest: string,
  seed: number,
  clients: number,
  operations: Operation[],
): string {
  // Where each written operation stands among the written ones, from 1, for a retry naming it.
  const position = new Map<number, number>();
  let kept = 0;
  // Every subject a written operation names.
  const subjects = new Set<string>();
  operations.forEach((operation, index) => {
    if (operation.dropped !== true) {
      kept += 1;
      position.set(index, kept);
      if (operation.subjectKey !== '') subjects.add(operation.subjectKey);
    }
  });
  const keptOperations = operations.filter((operation) => operation.dropped !== true);
  const written = keptOperations.map((operation, index) => {
    const members: [string, string][] = [
      ['operation_id', quote(uuidOf(BigInt(index) + 1n))],
      ['client', String(operation.client)],
      ['command', quote(operation.command)],
      ['subject_key', quote(operation.subjectKey)],
      ['invoked_at', String(operation.invokedAt)],
    ];
    if (operation.returnedAt !== undefined && operation.outcome !== undefined) {
      members.push(['returned_at', String(operation.returnedAt)]);
      members.push(['completion', quote('Returned')]);
      members.push(['outcome', quote(operation.outcome)]);
      if (operation.rows !== undefined) {
        const rows = writtenRows(operation, subjects, keptOperations);
        members.push(['rows', `[${rows.map(quote).join(',')}]`]);
      }
    } else {
      members.push(['completion', quote('Indeterminate')]);
    }
    const original = position.get(operation.retryOf - 1);
    if (operation.retryOf !== 0 && original !== undefined) {
      members.push(['retry_of', quote(uuidOf(BigInt(original)))]);
    }
    return jsonObject(members);
  });
  return jsonObject([
    ['format', quote('ess-history/1')],
    ['history_id', quote(uuidOf(BigInt(seed) & 0xffffffffffffn))],
    ['spec_digest', quote(digest)],
    ['seed', String(seed)],
    ['clients', String(clients)],
    ['operations', `[${written.join(',')}]`],
  ]);
}

/** Records the history `seed` names against a fresh target. */
async function recordHistory(
  p: Plan,
  newTarget: () => Answer<Target>,
  digest: string,
  seed: number,
  options: ConcurrentOptions,
): Promise<[string, Recording]> {
  const rng = new Mulberry32(seed);
  const clients = options.clients || rng.int(2, 4);
  const calls = options.calls || CONCURRENT_CALLS;
  const target = await newTarget();
  const scenario = {
    scenario: `explore/concurrent/seed-${seed}`,
    correlation: newHarness(p.system).correlation(),
  };
  await target.beginScenario(scenario);
  try {
    const h: Recording = {
      target,
      correlation: scenario.correlation,
      clock: 0,
      operations: [],
      indeterminate: 0,
      unsupported: [],
      ir: p.ir,
      injection: options.inject === true ? new SplitMix64(BigInt(seed) ^ INJECTION_STREAM) : null,
      arranging: true,
      redeliveries: [],
      retries: Array.from({ length: clients }, () => null),
      injected: newInjected(),
      tokens: Array.from({ length: clients }, () => ''),
    };
    const model = new Model();

    // The prefix: creations on client 0, one at a time, so the clients have subjects to share.
    const creating = p.commands.filter((command) =>
      list(command.node.outcomes).some((outcome: Node) => outcome.subject?.effect === 'creates'),
    );
    for (let index = 0; index < CONCURRENT_PREFIX && creating.length > 0; index += 1) {
      const command = rng.pick(creating);
      const step = draw(command, rng, model);
      if (step === null) continue;
      const created = await completeCall(h, await invokeCall(h, 0, command, step));
      if (created !== null) model.of(created.entity).push({ id: created.id, fields: {} });
    }

    // The workload: each client's calls, drawn against the subjects the prefix created. A call is
    // one of the commands or a read of one of the views, each as likely as another.
    const workload: Call[][] = [];
    for (let client = 0; client < clients; client += 1) {
      const own: Call[] = [];
      for (let call = 0; call < calls; call += 1) {
        for (let attempt = 0; attempt < ATTEMPTS_PER_STEP; attempt += 1) {
          const choice = rng.int(0, p.commands.length + p.views.length - 1);
          if (choice >= p.commands.length) {
            own.push({ command: null, step: null, view: p.views[choice - p.commands.length] });
            break;
          }
          const command = p.commands[choice] as Command;
          const step = draw(command, rng, model);
          if (step !== null) {
            own.push({ command, step, view: null });
            break;
          }
        }
      }
      workload.push(own);
    }

    // The interleaving: the clients' moves first, in client order, then each client's retry, then
    // each queued second delivery. Without `inject` only the first kind exists.
    h.arranging = false;
    const schedule = new SplitMix64(seed);
    const next = workload.map(() => 0);
    const flying: (Flight | null)[] = workload.map(() => null);
    for (;;) {
      const enabled: [number, number][] = [];
      workload.forEach((own, client) => {
        if (
          flying[client] !== null ||
          (h.retries[client] === null && (next[client] as number) < own.length)
        )
          enabled.push([0, client]);
      });
      workload.forEach((_, client) => {
        if (h.retries[client] !== null) enabled.push([1, client]);
      });
      h.redeliveries.forEach((_, slot) => enabled.push([2, slot]));
      if (enabled.length === 0) break;
      const [kind, client] = enabled[schedule.below(enabled.length)] as [number, number];
      const flight = flying[client] as Flight | null;
      if (kind === 1) {
        const retry = h.retries[client] as Retry;
        if (retry.flight === null) {
          retry.flight = await invokeRetry(h, client, retry);
        } else {
          h.retries[client] = null;
          await completeCall(h, retry.flight);
        }
      } else if (kind === 2) {
        await redeliver(h, client);
      } else if (flight !== null) {
        await completeCall(h, flight);
        flying[client] = null;
      } else {
        const call = (workload[client] as Call[])[next[client] as number] as Call;
        next[client] = (next[client] as number) + 1;
        flying[client] =
          call.view !== null
            ? invokeRead(h, client, call.view)
            : await invokeCall(h, client, call.command as Command, call.step as Step);
      }
    }
    return [historyText(digest, seed, clients, h.operations), h];
  } finally {
    await target.endScenario(scenario);
  }
}

/**
 * Records one concurrent history per seed against a fresh target, writes each into `out`, and runs
 * `ess verify conform check-history --path <path>` on it.
 *
 * Throws when `ess` is not on PATH (`NO_ESS`, before any target is made), when the model cannot be
 * used, when a history cannot be written, and when `ess` refuses one: a history nobody could check
 * is not a verdict. A violation or an unknown verdict is in the result.
 */
export async function exploreConcurrent(
  newTarget: () => Answer<Target>,
  options: ConcurrentOptions = {},
): Promise<ConcurrentResult> {
  const clients = options.clients ?? 0;
  if (clients !== 0 && !(clients >= 2 && clients <= 4)) {
    throw new Error(
      `explore: \`Clients\` is ${clients}; concurrent exploration runs 2 to 4 clients, or draws how many from each seed when it is 0`,
    );
  }
  if ((options.seeds ?? 0) < 0) {
    throw new Error(
      `explore: \`Seeds\` is ${String(options.seeds)}; concurrent exploration records at least one history, or 200 when it is 0`,
    );
  }
  if ((options.seed ?? 0) < 0) {
    throw new Error(
      `explore: \`Seed\` is ${String(options.seed)}; a replayed seed is at least 1, or none when it is 0`,
    );
  }
  if ((options.calls ?? 0) < 0) {
    throw new Error(
      `explore: \`Calls\` is ${String(options.calls)}; each client makes at least one call, or 3 when it is 0`,
    );
  }
  if (spawnSync('ess', ['--version'], { encoding: 'utf8' }).error !== undefined) {
    throw new Error(NO_ESS);
  }
  const path = options.path ?? '';
  const out = options.out ?? '';
  if (path === '') {
    throw new Error(
      'explore: concurrent exploration needs `Path`, the specification `ess` checks each history against',
    );
  }
  if (out === '') {
    throw new Error(
      'explore: concurrent exploration needs `Out`, the directory each history is written into',
    );
  }
  const ir = loadModel();
  if (nonEmpty(ir.preconditions)) {
    throw new Error(
      "explore: concurrent exploration does not run the specification's preconditions, so it does not record against one that declares them",
    );
  }
  const digest = String(strictJSON(packageFile('suite.json'))?.provenance?.spec_digest ?? '');
  const p = plan(ir, true);
  if (p.commands.length === 0) {
    throw new Error(
      'explore: the specification declares no command concurrent exploration can call',
    );
  }
  try {
    mkdirSync(out, { recursive: true });
  } catch (error) {
    throw new Error(`explore: cannot create ${out}: ${errorText(error)}`);
  }
  const seeds: number[] = [];
  if (options.seed) seeds.push(options.seed);
  else
    for (let seed = 1; seed <= (options.seeds || DEFAULT_CONCURRENT_SEEDS); seed += 1)
      seeds.push(seed);

  const result: ConcurrentResult = {
    histories: 0,
    linearizable: 0,
    violations: 0,
    unknown: 0,
    indeterminate: 0,
    excluded: [],
    allowExcluded: options.allowExcluded === true,
    verdicts: [],
    injected: newInjected(),
  };
  for (const seed of seeds) {
    if (p.commands.length === 0) break;
    let text: string;
    let recording: Recording;
    try {
      [text, recording] = await recordHistory(p, newTarget, digest, seed, options);
    } catch (error) {
      throw new Error(`explore: seed ${seed}: ${errorText(error)}`);
    }
    result.indeterminate += recording.indeterminate;
    addInjected(result.injected, recording.injected);
    for (const exclusion of recording.unsupported) {
      if (!result.excluded.some((earlier) => earlier.subject === exclusion.subject))
        result.excluded.push(exclusion);
    }
    const name = `history-${seed}.json`;
    const file = join(out, name);
    try {
      writeFileSync(file, text);
    } catch (error) {
      throw new Error(`explore: cannot write ${file}: ${errorText(error)}`);
    }
    const check = spawnSync(
      'ess',
      ['verify', 'conform', 'check-history', '--path', path, '--history', file],
      { encoding: 'utf8', maxBuffer: 1 << 30 },
    );
    if (check.error !== undefined) {
      throw new Error(`explore: cannot run \`ess\`: ${check.error.message}`);
    }
    let verdict: string;
    switch (check.status) {
      case 0:
        verdict = 'Linearizable';
        result.linearizable += 1;
        break;
      case 1:
        verdict = 'Violation';
        result.violations += 1;
        break;
      case 3:
        verdict = 'Unknown';
        result.unknown += 1;
        break;
      default:
        throw new Error(
          `explore: \`ess verify conform check-history\` refused ${name} (exit ${String(check.status)}): ${check.stderr.trim()}`,
        );
    }
    result.histories += 1;
    result.verdicts.push(verdict);
    if (verdict !== 'Linearizable' && result.failure === undefined) {
      result.failure = { seed, verdict, history: name, report: check.stdout };
    }
  }
  return result;
}

/** What `assertConcurrent` would fail with, or null when every history was linearizable. */
export function concurrentProblem(result: ConcurrentResult): string | null {
  const problems: string[] = [];
  if (result.violations !== 0 || result.unknown !== 0) {
    let message = `explore: ${result.violations} of ${result.histories} concurrent histories were violations and ${result.unknown} unknown`;
    const failure = result.failure;
    if (failure !== undefined) {
      message += `\nseed ${failure.seed} (${failure.history}): ${failure.verdict}\n${failure.report.replace(/\n+$/, '')}`;
    }
    problems.push(message);
  }
  if (result.excluded.length > 0 && !result.allowExcluded) {
    const lines = result.excluded.map((exclusion) => `  ${exclusion.subject}: ${exclusion.reason}`);
    problems.push(
      `explore: ${result.excluded.length} command(s) the target does not expose were left out of concurrent exploration:\n${lines.join('\n')}\naccept them explicitly with { allowExcluded: true }`,
    );
  }
  return problems.length === 0 ? null : problems.join('\n');
}

/** Throws unless every concurrent history was linearizable. `Unknown` is never a pass. */
export function assertConcurrent(result: ConcurrentResult): void {
  const problem = concurrentProblem(result);
  if (problem !== null) throw new Error(problem);
}
